	require([
        "jquery",
        'IdusClass_Core/js/idus'
    ], function($,idus){
    	if( idus.getCookie('opt_hight_contrast') == '1'){
    		$('body').addClass('hight_contrast');
    	}


		$('#hight_contrast_click').off('keypress').on('keypress',function(e){
			e.preventDefault();
			if (e.keyCode === 13) {
				if( $('body').hasClass('hight_contrast') ){
					$('body').removeClass('hight_contrast');
					idus.setCookie('opt_hight_contrast',0,30);
				}else{
					idus.setCookie('opt_hight_contrast',1,30);
					$('body').addClass('hight_contrast');
				}
			}
		});
	});


