p; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05e1\u05d5\u05e8 \u05d1\u05ea\u05db\u05dc\u05d9\u05ea \u05d4\u05d0\u05d9\u05e1\u05d5\u05e8 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d0\u05ea\u05e8 \u05d5\/\u05d0\u05d5 \u05d1\u05ea\u05d5\u05db\u05e0\u05d5, \u05d1\u05d0\u05d5\u05e4\u05df \u05d7\u05dc\u05e7\u05d9 \u05d0\u05d5 \u05db\u05d5\u05dc\u05dc, \u05dc\u05de\u05d8\u05e8\u05d5\u05ea \u05de\u05e1\u05d7\u05e8\u05d9\u05d5\u05ea.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d9\u05df \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05ea\u05d5\u05db\u05df \u05d1\u05d0\u05d5\u05e4\u05df \u05d7\u05dc\u05e7\u05d9 \u05d0\u05d5 \u05db\u05d5\u05dc\u05dc \u05dc\u05e9\u05dd \u05d4\u05e2\u05ea\u05e7\u05d4, \u05ea\u05d9\u05e7\u05d5\u05df, \u05e9\u05d9\u05e0\u05d5\u05d9, \u05e9\u05e2\u05ea\u05d5\u05e7, \u05e9\u05d9\u05d3\u05d5\u05e8, \u05d4\u05e6\u05d2\u05d4, \u05e4\u05e8\u05e1\u05d5\u05dd, \u05d4\u05e2\u05d1\u05e8\u05d4, \u05de\u05db\u05d9\u05e8\u05d4, \u05d0\u05d5 \u05d4\u05e4\u05e6\u05d4 \u05d1\u05db\u05dc \u05d3\u05e8\u05da \u05e9\u05d4\u05d9\u05d0 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05de\u05e9\u05ea\u05de\u05e9 \u05db\u05dc\u05e9\u05d4\u05d5.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05e8\u05d1\u05d5\u05ea, \u05d1\u05e4\u05e8\u05e1\u05d5\u05de\u05d9\u05dd \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05d9\u05dd \u05de\u05db\u05dc \u05e1\u05d5\u05d2 \u05e9\u05d4\u05d5\u05d0, \u05d1\u05ea\u05d5\u05db\u05e0\u05d5\u05ea \u05d5\u05d1\u05d9\u05d9\u05e9\u05d5\u05de\u05d9 \u05de\u05d7\u05e9\u05d1, \u05d1\u05d8\u05dc\u05e4\u05d5\u05e0\u05d9\u05dd, \u05d1\u05ea\u05e7\u05e9\u05d5\u05e8\u05ea \u05e1\u05dc\u05d5\u05dc\u05e8\u05d9\u05ea, \u05d1\u05e8\u05d3\u05d9\u05d5, \u05d1\u05d8\u05dc\u05d5\u05d5\u05d9\u05d6\u05d9\u05d4, \u05d1\u05d3\u05e4\u05d5\u05e1 \u05d0\u05d5 \u05d1\u05de\u05d3\u05d9\u05d4 \u05d0\u05d7\u05e8\u05ea \u05d5\u05db\u05dc \u05d4\u05e7\u05e9\u05d5\u05e8 \u05d5\u05d4\u05e0\u05d5\u05d1\u05e2 \u05de\u05db\u05da, \u05dc\u05dc\u05d0 \u05d4\u05e1\u05db\u05de\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4 \u05de\u05e8\u05d0\u05e9 \u05d5\u05d1\u05db\u05ea\u05d1.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;1.9.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8 \u05d7\u05dc\u05d9\u05dd \u05e2\u05dc \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8 \u05d5\u05d1\u05e9\u05d9\u05e8\u05d5\u05ea\u05d9\u05dd \u05d4\u05db\u05dc\u05d5\u05dc\u05d9\u05dd \u05d1\u05d5 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05db\u05dc \u05de\u05d7\u05e9\u05d1 \u05d0\u05d5 \u05de\u05db\u05e9\u05d9\u05e8 \u05ea\u05e7\u05e9\u05d5\u05e8\u05ea \u05d0\u05d7\u05e8( \u05db\u05d3\u05d5\u05d2\u05de\u05ea \u05d8\u05dc\u05e4\u05d5\u05df \u05e1\u05dc\u05d5\u05dc\u05d0\u05e8\u05d9, \u05de\u05d7\u05e9\u05d1\u05d9 \u05db\u05e3 \u05d9\u05d3 \u05dc\u05de\u05d9\u05e0\u05d9\u05d4\u05dd \u05d5\u05db\u05d9\u05d5\"\u05d1).&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05de\u05d5 \u05db\u05df \u05d4\u05dd \u05d7\u05dc\u05d9\u05dd \u05e2\u05dc \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8, \u05d1\u05d9\u05df \u05d0\u05dd \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05e8\u05e9\u05ea \u05d4\u05d0\u05d9\u05e0\u05d8\u05e8\u05e0\u05d8 \u05d5\u05d1\u05d9\u05df \u05d0\u05dd \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05db\u05dc \u05e8\u05e9\u05ea \u05d0\u05d5 \u05d0\u05de\u05e6\u05e2\u05d9 \u05ea\u05e7\u05e9\u05d5\u05e8\u05ea \u05d0\u05d7\u05e8\u05d9\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;1.10.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05d1\u05db\u05dc \u05e2\u05ea \u05d5\u05d0\u05e3 \u05de\u05d1\u05dc\u05d9 \u05dc\u05ea\u05ea \u05e2\u05dc \u05db\u05da \u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05e8\u05d0\u05e9, \u05e2\u05dc \u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9, \u05dc\u05d4\u05e4\u05e1\u05d9\u05e7 \u05d0\u05d5 \u05dc\u05d4\u05e9\u05d4\u05d5\u05ea \u05d0\u05ea \u05d4\u05e4\u05e2\u05dc\u05ea \u05d4\u05d0\u05ea\u05e8, \u05d1\u05d0\u05d5\u05e4\u05df \u05d7\u05dc\u05e7\u05d9 \u05d0\u05d5 \u05db\u05d5\u05dc\u05dc, \u05d5\/\u05d0\u05d5 \u05dc\u05ea\u05e7\u05df \u05d5\/\u05d0\u05d5 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d0\u05d5\u05e4\u05d9\u05d5 \u05d5\u05ea\u05d5\u05db\u05e0\u05d5.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05de\u05d5 \u05db\u05df, \u05d4\u05d7\u05d1\u05e8\u05d4 \u05de\u05e9\u05e7\u05d9\u05e2\u05d4 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e1\u05d1\u05d9\u05e8\u05d9\u05dd \u05e2\u05dc \u05de\u05e0\u05ea \u05dc\u05d4\u05d1\u05d8\u05d9\u05d7 \u05d0\u05ea \u05d4\u05ea\u05d7\u05d6\u05d5\u05e7\u05d4 \u05d5\u05d4\u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05e9\u05dc \u05d4\u05d0\u05ea\u05e8 \u05d5\u05ea\u05d5\u05db\u05e0\u05d5, \u05d0\u05d5\u05dc\u05dd, \u05e2\u05dc \u05d0\u05e3 \u05de\u05d0\u05de\u05e6\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d4\u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05d1\u05d0\u05ea\u05e8 \u05e2\u05e9\u05d5\u05d9\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e4\u05e8\u05e2\u05ea, \u05de\u05d5\u05e4\u05e1\u05e7\u05ea, \u05de\u05d5\u05e9\u05d4\u05d9\u05ea \u05d0\u05d5 \u05de\u05e2\u05d5\u05db\u05d1\u05ea,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2 \u05d0\u05d5 \u05d6\u05de\u05e0\u05d9, \u05d1\u05e9\u05dc \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05d0\u05d5 \u05d0\u05d9\u05e8\u05d5\u05e2\u05d9\u05dd \u05d0\u05e9\u05e8 \u05d0\u05d9\u05e0\u05dd \u05d1\u05d4\u05db\u05e8\u05d7 \u05d1\u05e9\u05dc\u05d9\u05d8\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d5 \u05e9\u05dc\u05d0 \u05de\u05e8\u05e6\u05d5\u05e0\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;1.11.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05de\u05e6\u05d4\u05d9\u05e8 \u05db\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05e9\u05d9\u05e2\u05e9\u05d4 \u05d1\u05d0\u05ea\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05e9\u05d9\u05de\u05d5\u05e9 \u05d7\u05d5\u05e7\u05d9, \u05d5\u05e2\u05dc \u05e4\u05d9 \u05d4\u05ea\u05e0\u05d0\u05d9\u05dd \u05e9\u05e0\u05e7\u05d1\u05e2\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;1.12.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05de\u05e2\u05df \u05d4\u05e1\u05d3\u05e8 \u05d4\u05d8\u05d5\u05d1 \u05d9\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d0\u05d9\u05df \u05d1\u05ea\u05e0\u05d0\u05d9\u05dd \u05d4\u05de\u05e4\u05d5\u05e8\u05d8\u05d9\u05dd \u05dc\u05e2\u05d9\u05dc \u05d5\u05dc\u05d4\u05dc\u05df \u05d1\u05db\u05d3\u05d9 \u05dc\u05d2\u05e8\u05d5\u05e2 \u05de\u05d4\u05ea\u05e0\u05d0\u05d9\u05dd \u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05d4\u05e0\u05d5\u05d2\u05e2\u05d9\u05dd \u05d5\u05d4\u05e7\u05e9\u05d5\u05e8\u05d9\u05dd \u05dc\u05d4\u05d6\u05de\u05e0\u05ea \u05de\u05d5\u05e6\u05e8\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05db\u05dc \u05dc\u05e7\u05d5\u05d7 \u05e9\u05d9\u05e8\u05db\u05d5\u05e9 \u05d5\/\u05d0\u05d5 \u05e9\u05d9\u05d9\u05e8\u05db\u05e9 \u05e2\u05d1\u05d5\u05e8\u05d5 \u05d0\u05d7\u05d3 \u05de\u05de\u05d5\u05e6\u05e8\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d9\u05d4\u05d9\u05d4 \u05db\u05e4\u05d5\u05e3 \u05dc\u05ea\u05e0\u05d0\u05d9\u05dd \u05d4\u05db\u05dc\u05dc\u05d9\u05dd \u05d5\u05dc\u05d4\u05d2\u05d1\u05dc\u05d5\u05ea \u05d4\u05de\u05e4\u05d5\u05e8\u05d8\u05d5\u05ea \u05d1\u05d8\u05e4\u05e1\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05db\u05e4\u05d9 \u05e9\u05d9\u05d4\u05d9\u05d5 \u05de\u05e2\u05ea \u05dc\u05e2\u05ea.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;1.13.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05e0\u05e0\u05d5 \u05de\u05de\u05dc\u05d9\u05e6\u05d9\u05dd \u05e2\u05dc \u05e7\u05e8\u05d9\u05d0\u05d4 \u05d7\u05d5\u05d6\u05e8\u05ea \u05e9\u05dc \u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05de\u05d9\u05d3\u05d9 \u05e4\u05e2\u05dd.\u003C\/p\u003E\r\n\u003Cp dir=\"rtl\"\u003E\u003Cstrong\u003E&nbsp; &nbsp; &nbsp;2.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003Cspan\u003E\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d0\u05e9\u05e8 \u05d2\u05d9\u05dc\u05dd \u05d0\u05d9\u05e0\u05d5 \u05e2\u05d5\u05dc\u05d4 \u05e2\u05dc 18 \u05e9\u05e0\u05d9\u05dd\u003C\/span\u003E\u003C\/strong\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"rtl\"\u003E&nbsp; &nbsp; &nbsp;2.1.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05e9\u05dc \u05d4\u05e2\u05d5\u05d1\u05d3\u05d4 \u05e9\u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05dc\u05d4\u05ea\u05d1\u05e7\u05e9 \u05dc\u05de\u05e1\u05d5\u05e8 \u05e4\u05e8\u05d8\u05d9\u05dd \u05d0\u05d9\u05e9\u05d9\u05d9\u05dd \u05e9\u05dc\u05d4\u05dd, \u05db\u05de\u05e4\u05d5\u05e8\u05d8 \u05d1\u05d4\u05de\u05e9\u05da, \u05d5\u05db\u05df \u05d1\u05e9\u05dc \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05de\u05d9\u05d3\u05e2 \u05d6\u05d4 \u05d5\u05d4\u05e1\u05d9\u05db\u05d5\u05e0\u05d9\u05dd \u05e9\u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05e2\u05e7\u05d1 \u05de\u05e1\u05d9\u05e8\u05ea\u05d5,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d0\u05e9\u05e8 \u05d2\u05d9\u05dc\u05dd \u05d0\u05d9\u05e0\u05d5 \u05e2\u05d5\u05dc\u05d4 \u05e2\u05dc 18 \u05e9\u05e0\u05d9\u05dd \u05e0\u05d3\u05e8\u05e9\u05d9\u05dd \u05dc\u05d9\u05d9\u05d3\u05e2 \u05d4\u05d5\u05e8\u05d9\u05d4\u05dd \u05d5\/\u05d0\u05d5 \u05d0\u05ea \u05d4\u05de\u05de\u05d5\u05e0\u05d9\u05dd \u05d4\u05d7\u05d5\u05e7\u05d9\u05d9\u05dd \u05e2\u05dc\u05d9\u05d4\u05dd \u05d1\u05d3\u05d1\u05e8 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d5\u05db\u05df \u05dc\u05e7\u05d1\u05dc \u05d0\u05ea \u05d0\u05d9\u05e9\u05d5\u05e8\u05dd \u05dc\u05d1\u05d9\u05e6\u05d5\u05e2 \u05db\u05dc \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05de\u05db\u05dc \u05e1\u05d5\u05d2 \u05e9\u05d4\u05d5\u05d0, \u05d1\u05de\u05e1\u05d2\u05e8\u05ea \u05d4\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;2.2.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d9\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d4\u05d4\u05d5\u05e8\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05d4\u05de\u05de\u05d5\u05e0\u05d9\u05dd \u05d7\u05dc\u05d4 \u05d4\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05dc\u05e4\u05e7\u05d7 \u05e2\u05dc \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05d9\u05dc\u05d3\u05d9\u05d4\u05dd \u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8, \u05d5\u05d1\u05d9\u05df \u05d4\u05d9\u05ea\u05e8, \u05dc\u05d4\u05e1\u05d1\u05d9\u05e8 \u05dc\u05de\u05e9\u05ea\u05de\u05e9 \u05e2\u05dc \u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d5\u05d4\u05d4\u05e9\u05dc\u05db\u05d5\u05ea \u05d4\u05e0\u05dc\u05d5\u05d5\u05ea \u05dc\u05ea\u05e0\u05d0\u05d9\u05dd \u05d0\u05dc\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;2.3.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05db\u05dc \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05d0\u05e9\u05e8 \u05ea\u05d1\u05d5\u05e6\u05e2 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05e1\u05d2\u05e8\u05ea \u05d4\u05d0\u05ea\u05e8 \u05de\u05d4\u05d5\u05d5\u05d4 \u05d4\u05e1\u05db\u05de\u05d4 \u05e9\u05dc \u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05d4\u05d5\u05e8\u05d9\u05d4\u05dd \u05d5\/\u05d0\u05d5 \u05d4\u05de\u05de\u05d5\u05e0\u05d9\u05dd \u05e2\u05dc\u05d9\u05d4\u05dd \u05dc\u05d0\u05de\u05d5\u05e8 \u05d1\u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9.\u003C\/p\u003E\r\n\u003Cp dir=\"rtl\"\u003E\u003Cstrong\u003E&nbsp; &nbsp;&nbsp;\u003C\/strong\u003E\u003Cstrong\u003E&nbsp;3.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003C\/strong\u003E\u003Cspan\u003E\u003Cstrong\u003E\u05e7\u05e0\u05d9\u05d9\u05df \u05e8\u05d5\u05d7\u05e0\u05d9\u003C\/strong\u003E\u003C\/span\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"rtl\"\u003E&nbsp; &nbsp; &nbsp;3.1.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05db\u05dc \u05d6\u05db\u05d5\u05d9\u05d5\u05ea \u05d4\u05e7\u05e0\u05d9\u05d9\u05df \u05d4\u05e8\u05d5\u05d7\u05e0\u05d9 \u05d1\u05d0\u05ea\u05e8, \u05dc\u05e8\u05d1\u05d5\u05ea \u05d4\u05e4\u05d8\u05e0\u05d8\u05d9\u05dd, \u05d6\u05db\u05d5\u05d9\u05d5\u05ea \u05d4\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd, \u05d4\u05de\u05d3\u05d2\u05de\u05d9\u05dd, \u05d4\u05e9\u05d9\u05d8\u05d5\u05ea \u05d5\u05d4\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05de\u05e1\u05d7\u05e8\u05d9\u05d9\u05dd, \u05d4\u05d9\u05e0\u05dd \u05e8\u05db\u05d5\u05e9\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05dc\u05d1\u05d3 \u05d5\u05d4\u05dd \u05de\u05d5\u05d2\u05e0\u05d9\u05dd \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05d7\u05e7\u05d9\u05e7\u05d4 \u05d4\u05dc\u05d0\u05d5\u05de\u05d9\u05ea \u05d5\u05d4\u05d1\u05d9\u05e0\u05dc\u05d0\u05d5\u05de\u05d9\u05ea \u05d4\u05e8\u05dc\u05d5\u05d5\u05e0\u05d8\u05d9\u05ea.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d6\u05db\u05d5\u05d9\u05d5\u05ea \u05d0\u05dc\u05d4 \u05d7\u05dc\u05d5\u05ea \u05d1\u05d9\u05df \u05d4\u05d9\u05ea\u05e8, \u05e2\u05dc \u05e2\u05d9\u05e6\u05d5\u05d1\u05d5 \u05d4\u05d2\u05e8\u05e4\u05d9 \u05e9\u05dc \u05d0\u05ea\u05e8 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d1\u05e1\u05d9\u05e1\u05d9 \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05d1\u05d5 (\u05dc\u05e8\u05d1\u05d5\u05ea \u05e8\u05e9\u05d9\u05de\u05d5\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd, \u05ea\u05d9\u05d0\u05d5\u05e8 \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d5\u05db\u05d3'), \u05e7\u05d5\u05d3 \u05d4\u05de\u05d7\u05e9\u05d1 \u05e9\u05dc \u05d4\u05d0\u05ea\u05e8, \u05d4\u05e7\u05d1\u05e6\u05d9\u05dd, \u05d4\u05ea\u05de\u05d5\u05e0\u05d5\u05ea, \u05d4\u05d5\u05d5\u05d9\u05d3\u05d0\u05d5, \u05d4\u05e9\u05de\u05e2, \u05d4\u05e1\u05de\u05dc\u05d9\u05dd,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05dc\u05d5\u05d2\u05d5, \u05e1\u05d9\u05de\u05e0\u05d9 \u05d4\u05de\u05e1\u05d7\u05e8, \u05db\u05ea\u05d5\u05d1\u05ea \u05d4\u05d0\u05d9\u05e0\u05d8\u05e8\u05e0\u05d8 \u05e9\u05dc\u05d5 \u05d5\u05db\u05dc \u05e4\u05e8\u05d8 \u05d0\u05d7\u05e8 \u05d4\u05e7\u05e9\u05d5\u05e8 \u05d1\u05d4\u05e4\u05e2\u05dc\u05ea\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.2.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d0\u05d9\u05df \u05dc\u05d4\u05e2\u05ea\u05d9\u05e7, \u05dc\u05e9\u05db\u05e4\u05dc, \u05dc\u05d4\u05e4\u05d9\u05e5, \u05dc\u05de\u05db\u05d5\u05e8, \u05dc\u05e9\u05d5\u05d5\u05e7, \u05d5\u05dc\u05ea\u05e8\u05d2\u05dd \u05de\u05d9\u05d3\u05e2 \u05db\u05dc\u05e9\u05d4\u05d5 \u05de\u05df \u05d4\u05d0\u05ea\u05e8 (\u05dc\u05e8\u05d1\u05d5\u05ea \u05e1\u05d9\u05de\u05e0\u05d9 \u05de\u05e1\u05d7\u05e8, \u05ea\u05de\u05d5\u05e0\u05d5\u05ea, \u05d8\u05e7\u05e1\u05d8\u05d9\u05dd \u05d5\u05e7\u05d5\u05d3-\u05de\u05d7\u05e9\u05d1) \u05d1\u05dc\u05d0 \u05e7\u05d1\u05dc\u05ea \u05e8\u05e9\u05d5\u05ea\u05d4 \u05d4\u05de\u05e4\u05d5\u05e8\u05e9\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05de\u05e8\u05d0\u05e9 \u05d5\u05d1\u05db\u05ea\u05d1.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.3.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d0\u05d9\u05df \u05dc\u05e2\u05e9\u05d5\u05ea \u05db\u05dc \u05e9\u05d9\u05de\u05d5\u05e9 \u05de\u05e1\u05d7\u05e8\u05d9 \u05d1\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05d4\u05de\u05ea\u05e4\u05e8\u05e1\u05de\u05d9\u05dd \u05e2\"\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d1\u05d1\u05e1\u05d9\u05e1 \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d1\u05e8\u05e9\u05d9\u05de\u05d5\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d4\u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d5 \u05d0\u05d5 \u05d1\u05e4\u05e8\u05d8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd \u05d4\u05de\u05ea\u05e4\u05e8\u05e1\u05de\u05d9\u05dd \u05e2\"\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05dc\u05d0 \u05e7\u05d1\u05dc\u05ea \u05d4\u05e1\u05db\u05de\u05ea\u05d4 \u05de\u05e8\u05d0\u05e9 \u05d5\u05d1\u05db\u05ea\u05d1.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.4.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05de\u05ea\u05d9\u05e8\u05d4 \u05dc\u05d4\u05e6\u05d9\u05d2 \u05d0\u05ea \u05d4\u05d0\u05ea\u05e8 \u05d1\u05ea\u05d5\u05da \u05de\u05e1\u05d2\u05e8\u05ea (\u003Cb\u003EFrame\u003C\/b\u003E), \u05d2\u05dc\u05d5\u05d9\u05d4 \u05d0\u05d5 \u05e1\u05de\u05d5\u05d9\u05d4 \u05d5\u05db\u05df \u05dc\u05e7\u05e9\u05e8 \u05dc\u05e2\u05de\u05d5\u05d3\u05d9\u05dd \u05d4\u05de\u05e6\u05d5\u05d9\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05d5 (\"\u003Cb\u003EDEEP LINK\u003C\/b\u003E\"), \u05d0\u05d5 \u05dc\u05e2\u05de\u05d5\u05d3 \u05d4\u05d1\u05d9\u05ea \u05d1\u05dc\u05d1\u05d3.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d4\u05d9\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05d4\u05d5\u05e8\u05d5\u05ea \u05dc\u05de\u05e9\u05ea\u05de\u05e9 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05e4\u05e8\u05e1\u05d5\u05dd \u05d0\u05d5 \u05de\u05d9\u05d3\u05e2 \u05d1\u05d5 \u05e0\u05e2\u05e9\u05d4 \u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05d5\u05e4\u05df \u05e9\u05dc\u05d8\u05e2\u05de\u05d4 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05d0\u05d9\u05e0\u05d8\u05e8\u05e1\u05d9\u05dd \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d5 \u05d1\u05e7\u05e0\u05d9\u05d9\u05e0\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.5.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d0\u05d9\u05df \u05dc\u05d4\u05e6\u05d9\u05d2 \u05d0\u05ea \u05d4\u05d0\u05ea\u05e8 \u05d1\u05e2\u05d9\u05e6\u05d5\u05d1 \u05d0\u05d5 \u05de\u05de\u05e9\u05e7 \u05d2\u05e8\u05e4\u05d9 \u05e9\u05d5\u05e0\u05d9\u05dd \u05de\u05d0\u05dc\u05d4 \u05e9\u05e2\u05d9\u05e6\u05d1\u05d4 \u05dc\u05d5 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d0\u05dc\u05d0 \u05d1\u05db\u05e4\u05d5\u05e3 \u05dc\u05e7\u05d1\u05dc\u05ea \u05d4\u05e1\u05db\u05de\u05ea\u05d5 \u05dc\u05db\u05da \u05de\u05e8\u05d0\u05e9 \u05d5\u05d1\u05db\u05ea\u05d1.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.6.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05e9\u05dd \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d4\u05e9\u05dd \"\u05d0\u05d5\u05e4\u05d8\u05d9\u05e7\u05e0\u05d4 \u05d4\u05d0\u05d5\u05e4\u05d8\u05d9\u05e1\u05d8\u05d5\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df\" \u05d5\u05db\u05df \u05e9\u05de\u05d5\u05ea \u05de\u05d5\u05ea\u05d2\u05d9 \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd, \u05e1\u05d9\u05de\u05e0\u05d9 \u05d4\u05de\u05e1\u05d7\u05e8 \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 (\u05d1\u05d9\u05df \u05d0\u05dd \u05e0\u05e8\u05e9\u05de\u05d5 \u05d5\u05d1\u05d9\u05df \u05d0\u05dd \u05dc\u05d0\u05d5)- \u05d4\u05dd \u05db\u05d5\u05dc\u05dd \u05e8\u05db\u05d5\u05e9\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05dc\u05d1\u05d3.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d9\u05df \u05dc\u05e2\u05e9\u05d5\u05ea \u05d1\u05d4\u05dd \u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05dc\u05d0 \u05e7\u05d1\u05dc\u05ea \u05d4\u05e1\u05db\u05de\u05ea\u05d4 \u05d1\u05db\u05ea\u05d1 \u05d5\u05de\u05e8\u05d0\u05e9.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.7.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d0\u05d9\u05d9\u05e7\u05d5\u05e0\u05d9\u05dd (\u003Cb\u003Eicons\u003C\/b\u003E), \u05db\u05dc \u05de\u05d9\u05d3\u05e2 \u05d5\/\u05d0\u05d5 \u05ea\u05e6\u05d5\u05d2\u05d4 \u05d4\u05de\u05d5\u05e4\u05d9\u05e2\u05d4 \u05d1\u05d0\u05ea\u05e8, \u05dc\u05e8\u05d1\u05d5\u05ea \u05d2\u05e8\u05e4\u05d9\u05e7\u05d4, \u05e2\u05d9\u05e6\u05d5\u05d1, \u05d4\u05e6\u05d2\u05d4 \u05de\u05d9\u05dc\u05d5\u05dc\u05d9\u05ea, \u05e1\u05d9\u05de\u05e0\u05d9 \u05de\u05e1\u05d7\u05e8, \u05e1\u05d9\u05de\u05e0\u05d9 \u05dc\u05d5\u05d2\u05d5 (\u003Cb\u003Elogo\u003C\/b\u003E) \u05d5\u05db\u05df \u05e2\u05e8\u05d9\u05db\u05ea\u05dd \u05d5\u05d4\u05e6\u05d2\u05ea\u05dd \u05e9\u05dc \u05d0\u05dc\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05e0\u05dd \u05d1\u05d1\u05e2\u05dc\u05d5\u05ea \u05d1\u05dc\u05e2\u05d3\u05d9\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4. \u05db\u05dc \u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05e7\u05e0\u05d9\u05d9\u05e0\u05d4 \u05d6\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d9\u05e2\u05e9\u05d4 \u05e2\u05dc \u05e4\u05d9 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05ea\u05e7\u05e0\u05d5\u05df \u05d6\u05d4 \u05d1\u05dc\u05d1\u05d3.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.8.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05db\u05dc \u05de\u05d5\u05e1\u05e8 \u05de\u05d9\u05d3\u05e2 \u05dc\u05e4\u05e8\u05e1\u05d5\u05dd \u05d1\u05d0\u05ea\u05e8, \u05d5\u05d9\u05d4\u05d9\u05d4 \u05d6\u05d4 \u05de\u05d0\u05de\u05e8, \u05d9\u05d3\u05d9\u05e2\u05d4, \u05ea\u05d2\u05d5\u05d1\u05d4 \u05d0\u05d5 \u05db\u05dc \u05de\u05d9\u05d3\u05e2 \u05d0\u05d7\u05e8, \u05de\u05d0\u05e9\u05e8 \u05de\u05e1\u05d9\u05e8\u05ea\u05d5 \u05dc\u05e4\u05e8\u05e1\u05d5\u05dd \u05d5\u05db\u05d9 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05dc \u05db\u05dc \u05d4\u05d6\u05db\u05d5\u05d9\u05d5\u05ea \u05d1\u05d5 \u05d5\u05e8\u05e9\u05d0\u05d9 \u05dc\u05de\u05e1\u05d5\u05e8\u05df.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05de\u05e1\u05d9\u05e8\u05ea \u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05d5\u05d0 \u05de\u05e7\u05e0\u05d4 \u05dc\u05d7\u05d1\u05e8\u05d4 \u05e8\u05d9\u05e9\u05d9\u05d5\u05df \u05d7\u05d9\u05e0\u05dd, \u05db\u05dc\u05dc \u05e2\u05d5\u05dc\u05de\u05d9, \u05dc\u05d0 \u05d1\u05dc\u05e2\u05d3\u05d9 \u05d5\u05d1\u05dc\u05ea\u05d9 \u05de\u05d5\u05d2\u05df, \u05dc\u05d4\u05e2\u05ea\u05d9\u05e7, \u05dc\u05e9\u05db\u05e4\u05dc, \u05dc\u05d4\u05e4\u05d9\u05e5, \u05dc\u05e9\u05d5\u05d5\u05e7, \u05dc\u05de\u05e1\u05d5\u05e8 \u05dc\u05e6\u05d9\u05d1\u05d5\u05e8 \u05d5\u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05de\u05d9\u05d3\u05e2 \u05db\u05d0\u05de\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05db\u05dc \u05d0\u05de\u05e6\u05e2\u05d9 \u05ea\u05e7\u05e9\u05d5\u05e8\u05ea \u05d0\u05d5 \u05e4\u05e8\u05e1\u05d5\u05dd \u05d0\u05d7\u05e8 \u05d4\u05de\u05e9\u05de\u05e9 \u05d0\u05d5\u05ea\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;3.9.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d0\u05d9\u05df \u05dc\u05e2\u05e9\u05d5\u05ea \u05e9\u05d5\u05dd \u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05e9\u05d5\u05dd \u05e1\u05d9\u05de\u05df \u05de\u05e1\u05d7\u05e8\u05d9 \u05d0\u05d5 \u05e2\u05d9\u05e6\u05d5\u05d1 \u05e9\u05dc \u05de\u05d5\u05e6\u05e8 \u05d0\u05d5 \u05d3\u05d2\u05dd \u05d4\u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05d0\u05d5 \u05d1\u05e6\u05d9\u05dc\u05d5\u05de\u05d9\u05dd \u05d4\u05de\u05e6\u05d5\u05d9\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05e9\u05d4\u05d9\u05e0\u05dd \u05e7\u05e0\u05d9\u05d9\u05df \u05e8\u05d5\u05d7\u05e0\u05d9 \u05de\u05d5\u05d2\u05df, \u05d4\u05df \u05de\u05db\u05d7 \u05d4\u05d3\u05d9\u05df \u05d1\u05d9\u05e9\u05e8\u05d0\u05dc \u05d5\u05d4\u05df \u05de\u05db\u05d7 \u05d0\u05de\u05e0\u05d5\u05ea \u05d1\u05d9\u05e0\u05dc\u05d0\u05d5\u05de\u05d9\u05ea \u05d0\u05dc\u05d9\u05d4\u05df \u05d4\u05e6\u05d8\u05e8\u05e4\u05d4 \u05de\u05d3\u05d9\u05e0\u05ea \u05d9\u05e9\u05e8\u05d0\u05dc.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;\u003Cstrong\u003E4.\u003C\/strong\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003Cb\u003E\u003Cspan\u003E\u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea \u05d4\u05e4\u05e8\u05d8\u05d9\u05d5\u05ea\u003C\/span\u003E\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;4.1.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05de\u05db\u05d1\u05d3\u05ea \u05d0\u05ea \u05e4\u05e8\u05d8\u05d9\u05d5\u05ea\u05d5 \u05e9\u05dc \u05db\u05dc \u05d0\u05d3\u05dd \u05e9\u05de\u05d1\u05e7\u05e8 \u05d1\u05d0\u05ea\u05e8 \u05db\u05de\u05e4\u05d5\u05e8\u05d8&nbsp;\u003Ca href=\"\/\u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea-\u05e4\u05e8\u05d8\u05d9\u05d5\u05ea\"\u003E\u05d1\u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea \u05d4\u05e4\u05e8\u05d8\u05d9\u05d5\u05ea\u003C\/a\u003E.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp;&nbsp;\u003Cstrong\u003E&nbsp; &nbsp;5\u003C\/strong\u003E.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003Cb\u003E\u003Cspan\u003E\u05de\u05d5\u05e6\u05e8\u05d9\u05dd\u003C\/span\u003E\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;5.1.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d0\u05ea\u05e8 \u05de\u05e9\u05de\u05e9 \u05db\u05d0\u05de\u05d5\u05e8, \u05d1\u05d9\u05df \u05d4\u05d9\u05ea\u05e8, \u05dc\u05de\u05d8\u05e8\u05d5\u05ea \u05de\u05db\u05d9\u05e8\u05ea \u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d4\u05de\u05e9\u05d5\u05d5\u05e7\u05d9\u05dd \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;5.2.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d4\u05de\u05d5\u05e6\u05d2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05d4\u05d9\u05e0\u05dd \u05e8\u05e7 \u05d7\u05dc\u05e7 \u05de\u05de\u05d5\u05e6\u05e8\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d4\u05e0\u05de\u05db\u05e8\u05d9\u05dd \u05e2\u05dc \u05d9\u05d3\u05d4 \u05de\u05e2\u05ea \u05dc\u05e2\u05ea. \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05e9\u05e0\u05d5\u05ea \u05d1\u05db\u05dc \u05e2\u05ea, \u05d5\u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9 \u05d5\u05dc\u05dc\u05d0 \u05db\u05dc \u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05e8\u05d0\u05e9, \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d4\u05de\u05d5\u05e6\u05e2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05d4\u05d7\u05dc\u05d9\u05e4\u05dd \u05d0\u05d5 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0\u05dd \u05de\u05df \u05d4\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;5.3.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d9\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d4\u05ea\u05de\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05d5\u05e6\u05d2\u05d5\u05ea \u05d1\u05d0\u05ea\u05e8 \u05e0\u05d5\u05e2\u05d3\u05d5 \u05dc\u05d4\u05de\u05d7\u05e9\u05d4 \u05d1\u05dc\u05d1\u05d3.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp;&nbsp;\u003Cstrong\u003E&nbsp; &nbsp;6.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003C\/strong\u003E&nbsp; &nbsp;&nbsp;\u003Cb\u003E\u003Cspan\u003E\u05e8\u05db\u05d9\u05e9\u05d4 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05d0\u05ea\u05e8\u003C\/span\u003E\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E\u003Cb\u003E\u003Cspan\u003E\u003Cbr \/\u003E\u003C\/span\u003E\u003C\/b\u003E&nbsp; &nbsp; &nbsp;6.1.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05e8\u05e9\u05d0\u05d9 \u05dc\u05d1\u05e6\u05e2 \u05e8\u05db\u05d9\u05e9\u05d5\u05ea \u05d1\u05d0\u05ea\u05e8 \u05e8\u05e7 \u05de\u05e9\u05ea\u05de\u05e9 \u05e9\u05d4\u05e0\u05d5 \u05db\u05e9\u05d9\u05e8 \u05dc\u05d1\u05e6\u05e2 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05de\u05e9\u05e4\u05d8\u05d9\u05d5\u05ea \u05de\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea. \u05d1\u05db\u05dc\u05dc \u05d6\u05d4 \u05de\u05e6\u05d4\u05d9\u05e8 \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05db\u05d9 \u05d4\u05d9\u05e0\u05d5 \u05d1\u05df 18 \u05e9\u05e0\u05d4 \u05d0\u05d5 \u05de\u05d1\u05d5\u05d2\u05e8 \u05d9\u05d5\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.2.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05e2\u05ea \u05ea\u05e9\u05dc\u05d5\u05dd \u05d1\u05d2\u05d9\u05df \u05d4\u05d6\u05de\u05e0\u05d4 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9, \u05d9\u05e2\u05e9\u05d4 \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9 \u05ea\u05e7\u05e3 \u05e9\u05d4\u05d5\u05e0\u05e4\u05e7 \u05db\u05d3\u05d9\u05df \u05e2\"\u05d9 \u05d0\u05d7\u05ea \u05de\u05d7\u05d1\u05e8\u05d5\u05ea \u05db\u05e8\u05d8\u05d9\u05e1\u05d9 \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d4\u05e4\u05e2\u05d9\u05dc\u05d5\u05ea \u05d2\u05dd \u05d1\u05d9\u05e9\u05e8\u05d0\u05dc,\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05d4\u05d9\u05e0\u05d5 \u05d1\u05e2\u05dc\u05d9\u05d5 \u05d0\u05d5 \u05e7\u05d9\u05d1\u05dc \u05d0\u05ea \u05d4\u05e1\u05db\u05de\u05ea\u05d5 \u05de\u05e8\u05e6\u05d5\u05df \u05e9\u05dc \u05d1\u05e2\u05dc \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9 \u05db\u05d0\u05de\u05d5\u05e8, \u05dc\u05e2\u05e9\u05d5\u05ea \u05d1\u05d5 \u05e9\u05d9\u05de\u05d5\u05e9.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.3.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e9\u05d5\u05de\u05e8\u05ea \u05dc\u05e2\u05e6\u05de\u05d4 \u05d0\u05ea \u05d4\u05d6\u05db\u05d5\u05ea \u05dc\u05de\u05e0\u05d5\u05e2 \u05d0\u05ea \u05d4\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e8\u05db\u05d9\u05e9\u05d5\u05ea \u05d5\/\u05d0\u05d5 \u05dc\u05d1\u05d8\u05dc \u05e8\u05db\u05d9\u05e9\u05d5\u05ea \u05e9\u05dc \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05e9\u05d4\u05ea\u05e0\u05d4\u05d2\u05d5\u05ea\u05dd \u05d0\u05d9\u05e0\u05d4 \u05d4\u05d5\u05dc\u05de\u05ea \u05d0\u05d5 \u05e9\u05d0\u05d9\u05e0\u05d4 \u05dc\u05e4\u05d9 \u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9,\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\/\u05d0\u05d5 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05ea\u05e7\u05e0\u05d5\u05df \u05d6\u05d4 \u05d0\u05d5 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d4\u05de\u05e0\u05e1\u05d9\u05dd \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05e0\u05d9\u05d4\u05d5\u05dc\u05d5 \u05d4\u05ea\u05e7\u05d9\u05df \u05e9\u05dc \u05d4\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.4.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05e9\u05de\u05d5\u05ea \u05d7\u05d1\u05e8\u05d5\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d5\/\u05d0\u05d5 \u05d4\u05db\u05e8\u05d8\u05d9\u05e1\u05d9\u05dd \u05d1\u05d4\u05dd \u05e0\u05d9\u05ea\u05df \u05dc\u05e2\u05e9\u05d5\u05ea \u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05dd:&nbsp;\u003Cstrong\u003E\u05dc\u05d0\u05d5\u05de\u05d9 \u05e7\u05d0\u05e8\u05d3, \u05d9\u05e9\u05e8\u05d0\u05db\u05e8\u05d8,&nbsp; \u05de\u05d0\u05e1\u05d8\u05e8\u05db\u05d0\u05e8\u05d3, \u05d5\u05d9\u05d6\u05d4 \u05db\u05d0\u05dc.\u003Cbr \/\u003E\u003C\/strong\u003E&nbsp; &nbsp; &nbsp;6.5.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05e2\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d6\u05de\u05e0\u05d4 \u05d1\u05d0\u05ea\u05e8 \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05d9\u05d9\u05d3\u05e8\u05e9 \u05dc\u05d4\u05db\u05e0\u05d9\u05e1 \u05d0\u05ea \u05e4\u05e8\u05d8\u05d9 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05e9\u05d1\u05e8\u05e9\u05d5\u05ea\u05d5 \u05d5\u05db\u05df \u05d4\u05d5\u05d0 \u05e2\u05e9\u05d5\u05d9 \u05dc\u05d4\u05d9\u05d3\u05e8\u05e9 \u05dc\u05e1\u05e4\u05e7 \u05de\u05e1\u05de\u05db\u05d9\u05dd \u05de\u05d6\u05d4\u05d9\u05dd. \u05dc\u05d3\u05d5\u05d2\u05de\u05d4, \u05d4\u05e2\u05ea\u05e7 \u05ea\u05e2\u05d5\u05d3\u05ea \u05d6\u05d4\u05d5\u05ea, \u05e8\u05d9\u05e9\u05d9\u05d5\u05df \u05e0\u05d4\u05d9\u05d2\u05d4, \u05d3\u05e8\u05db\u05d5\u05df, \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9 \u05d7\u05ea\u05d5\u05dd \u05d5\u05db\u05d9\u05d5\u05e6\u05d0 \u05d1\u05d6\u05d0\u05ea.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d9\u05de\u05d5\u05ea \u05d4\u05d6\u05d4\u05d5\u05ea \u05e0\u05d5\u05e2\u05d3\u05d4, \u05d1\u05d9\u05df \u05d4\u05d9\u05ea\u05e8, \u05e2\u05dc \u05de\u05e0\u05ea \u05dc\u05d4\u05d2\u05df \u05e2\u05dc \u05d4\u05d0\u05ea\u05e8 \u05d5\/\u05d0\u05d5 \u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.6.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d4\u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05e8\u05db\u05d9\u05e9\u05d4 \u05d1\u05d0\u05ea\u05e8 \u05de\u05ea\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05de\u05e1\u05d5\u05e8 \u05e4\u05e8\u05d8\u05d9\u05dd \u05e0\u05db\u05d5\u05e0\u05d9\u05dd \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d1\u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05db\u05d9\u05e9\u05d4. \u05d0\u05d9\u05df \u05dc\u05de\u05e1\u05d5\u05e8 \u05e4\u05e8\u05d8\u05d9\u05dd \u05e9\u05dc \u05e6\u05d3 \u05e9\u05dc\u05d9\u05e9\u05d9 \u05db\u05dc\u05e9\u05d4\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.7.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05d0\u05dd \u05d5\u05d1\u05e2\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d1\u05d0\u05ea\u05e8 \u05d9\u05de\u05e1\u05e8\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05e4\u05e8\u05d8\u05d9 \u05d6\u05d9\u05d4\u05d5\u05d9 \u05e9\u05d2\u05d5\u05d9\u05d9\u05dd, \u05dc\u05e8\u05d1\u05d5\u05ea \u05db\u05ea\u05d5\u05d1\u05ea, \u05ea\u05e2\u05d5\u05d3\u05ea \u05d6\u05d4\u05d5\u05ea, \u05e4\u05e8\u05d8\u05d9 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d5\u05db\u05d5',&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d5 \u05d1\u05d0\u05dd \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05d0 \u05ea\u05d0\u05d5\u05e9\u05e8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d5\u05dc\u05d0 \u05d9\u05e4\u05e2\u05dc \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05ea\u05d5\u05da \u05e9\u05d1\u05d5\u05e2 \u05d9\u05de\u05d9\u05dd \u05de\u05de\u05d5\u05e2\u05d3 \u05e7\u05d1\u05dc\u05ea \u05d4\u05d4\u05d5\u05d3\u05e2\u05d4 \u05e2\u05dc \u05e1\u05d9\u05e8\u05d5\u05d1 \u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9, \u05dc\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d5\u05de\u05ea\u05df \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d7\u05d3\u05e9 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d4\u05d0 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05d6\u05de\u05e0\u05ea\u05da \u05e2\u05dc \u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.8.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05d8\u05d5\u05e4\u05e1 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d9\u05de\u05e1\u05d5\u05e8 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d0\u05ea \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea\u05d5 \u05d4\u05d5\u05d0 \u05de\u05e2\u05d5\u05e0\u05d9\u05d9\u05df \u05dc\u05d1\u05e6\u05e2 \u05d0\u05ea \u05d4\u05e8\u05db\u05d9\u05e9\u05d4. \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05d1\u05d4\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d9\u05e0\u05dd \u05db\u05d3\u05dc\u05e7\u05de\u05df:&nbsp;\u003Cstrong\u003EPAYPAL \u05d0\u05d5 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9.\u003Cbr \/\u003E\u003C\/strong\u003E&nbsp; &nbsp; &nbsp;6.9.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05de\u05d8\u05e2\u05de\u05d9\u05dd \u05e9\u05dc \u05d0\u05d1\u05d8\u05d7\u05ea \u05de\u05d9\u05d3\u05e2 \u05d5\u05d4\u05d2\u05e0\u05d4 \u05e2\u05dc \u05e4\u05e8\u05d8\u05d9\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7, \u05d1\u05d0\u05dd \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d4\u05d9\u05e0\u05d5 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9, \u05e0\u05ea\u05d5\u05e0\u05d9 \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05dc\u05d0 \u05d9\u05e9\u05de\u05e8\u05d5 \u05d1\u05de\u05dc\u05d5\u05d0\u05dd,\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(\u05e8\u05e7 \u05d0\u05e8\u05d1\u05e2 \u05e1\u05e4\u05e8\u05d5\u05ea \u05d0\u05d7\u05e8\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd) \u05d1\u05de\u05d0\u05d2\u05e8 \u05d4\u05de\u05d9\u05d3\u05e2 \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d5\u05d9\u05e9\u05de\u05e9\u05d5 \u05e8\u05e7 \u05dc\u05e6\u05d5\u05e8\u05da \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d4\u05e1\u05e4\u05e6\u05d9\u05e4\u05d9\u05ea.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.10.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05d0\u05d7\u05e8 \u05d4\u05d6\u05e0\u05ea \u05e4\u05e8\u05d8\u05d9 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d0\u05d5 \u05e4\u05e8\u05d8\u05d9 PAYPAL \u05d5\u05d4\u05e4\u05e8\u05d8\u05d9\u05dd \u05d4\u05d0\u05d9\u05e9\u05d9\u05d9\u05dd, \u05d9\u05d0\u05e9\u05e8 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d0\u05ea \u05d4\u05d6\u05de\u05e0\u05ea\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05dc \u05db\u05e4\u05ea\u05d5\u05e8 \"\u003Cb\u003E\u05d1\u05e6\u05e2 \u05ea\u05e9\u05dc\u05d5\u05dd\u003C\/b\u003E\" (\u05dc\u05d4\u05dc\u05df: \"\u003Cb\u003E\u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4\u003C\/b\u003E\").&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.10.1&nbsp; &nbsp; &nbsp; \u05d1\u05d0\u05dd \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d4\u05d9\u05e0\u05d5 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9, \u05d4\u05de\u05e2\u05e8\u05db\u05ea \u05ea\u05d1\u05e6\u05e2 \u05d0\u05d9\u05de\u05d5\u05ea \u05e4\u05e8\u05d8\u05d9 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d7\u05d1\u05e8\u05ea \u05d4\u05e1\u05dc\u05d9\u05e7\u05d4.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05db\u05dc \u05e9\u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05d0 \u05d0\u05d5\u05e9\u05e8\u05d4 \u05e2\"\u05d9 \u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9, \u05d9\u05e7\u05d1\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4, \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05d0 \u05ea\u05d1\u05d5\u05e6\u05e2 \u05d5\u05d9\u05d7\u05d5\u05dc\u05d5 \u05d4\u05d5\u05e8\u05d0\u05d5 \u05e1\u05e2\u05d9\u05e3 6.12 \u05dc\u05d4\u05dc\u05df.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.10.2&nbsp; &nbsp; &nbsp; \u05d1\u05d0\u05dd \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d4\u05d9\u05e0\u05d5 PAYPAL, \u05d9\u05d1\u05d5\u05e6\u05e2 \u05d0\u05d9\u05de\u05d5\u05ea \u05d7\u05e9\u05d1\u05d5\u05df \u05de\u05d5\u05dc \u05d7\u05d1\u05e8\u05ea PAYPAL,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05db\u05dc \u05e9\u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05d0 \u05d0\u05d5\u05e9\u05e8\u05d4 \u05e2\"\u05d9 \u05d7\u05d1\u05e8\u05ea PAYPAL, \u05d9\u05e7\u05d1\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4, \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05d0 \u05ea\u05d1\u05d5\u05e6\u05e2 \u05d5\u05d9\u05d7\u05d5\u05dc\u05d5 \u05d4\u05d5\u05e8\u05d0\u05d5 \u05e1\u05e2\u05d9\u05e3 6.12 \u05dc\u05d4\u05dc\u05df\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.11.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05d0\u05d7\u05e8 \u05e9\u05d4\u05ea\u05e7\u05d1\u05dc \u05d0\u05e6\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05de\u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d0\u05d5 \u05dePAYPAL \u05d1\u05d2\u05d9\u05df \u05d4\u05d4\u05d6\u05de\u05e0\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05d4\u05d7\u05d1\u05e8\u05d4 \u05d5\u05d5\u05d9\u05d3\u05d0\u05d4 \u05db\u05d9 \u05d4\u05e4\u05e8\u05d9\u05d8 \u05e7\u05d9\u05d9\u05dd \u05d1\u05de\u05dc\u05d0\u05d9 \u05ea\u05d9\u05e9\u05dc\u05d7 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d5\u05d3\u05e2\u05ea \u05d3\u05d5\u05d0\u05e8 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9 \u05dc\u05db\u05ea\u05d5\u05d1\u05ea \u05e9\u05d4\u05d5\u05d6\u05e0\u05d4 \u05d1\u05e2\u05ea \u05de\u05d9\u05dc\u05d5\u05d9 \u05d8\u05d5\u05e4\u05e1 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05e2\u05dc \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4.&nbsp;(\u05dc\u05d4\u05dc\u05df: \"\u003Cb\u003E\u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4\u003C\/b\u003E\").\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.12.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05de\u05e2\u05df \u05d4\u05e1\u05e8 \u05e1\u05e4\u05e7 \u05d9\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05ea\u05d0\u05d5\u05e9\u05e8 \u05d1\u05db\u05e4\u05d5\u05e3 \u05dc:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.12.1.&nbsp; &nbsp; &nbsp;\u05d1\u05d0\u05dd \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d4\u05d9\u05e0\u05d5 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9 \u05d0\u05d5 PAYPAL- \u05d0\u05d9\u05de\u05d5\u05ea \u05e4\u05e8\u05d8\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05d5\u05e7\u05d1\u05dc\u05ea \u05d0\u05d9\u05e9\u05d5\u05e8 \u05e2\u05dc \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05de\u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d0\u05d5 \u05de\u05d7\u05d1\u05e8\u05ea PAYPAL .&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05dc\u05d0 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05db\u05d0\u05de\u05d5\u05e8, \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05d0 \u05ea\u05d0\u05d5\u05e9\u05e8 \u05d5\u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05de\u05d7\u05d5\u05d9\u05d1\u05ea \u05db\u05dc\u05e4\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d1\u05e9\u05d5\u05dd \u05d3\u05e8\u05da \u05dc\u05e8\u05d1\u05d5\u05ea \u05dc\u05d0 \u05d1\u05e9\u05de\u05d9\u05e8\u05ea \u05d4\u05de\u05d5\u05e6\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;6.12.2.&nbsp; &nbsp; &nbsp;\u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05d1\u05de\u05dc\u05d0\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05de\u05d5\u05e2\u05d3 \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4. \u05de\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05de\u05ea\u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d7\u05d6\u05d9\u05e7 \u05de\u05dc\u05d0\u05d9 \u05e9\u05dc \u05db\u05dc \u05d4\u05d3\u05d2\u05de\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d4\u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05db\u05dc \u05e9\u05d4\u05de\u05d5\u05e6\u05e8 \u05dc\u05d0 \u05e7\u05d9\u05d9\u05dd \u05d1\u05de\u05dc\u05d0\u05d9, \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d4\u05d9\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05e9\u05dc\u05d0 \u05dc\u05d0\u05e9\u05e8 \u05d0\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d9\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d2\u05dd \u05d0\u05dd \u05dc\u05d0 \u05e6\u05d5\u05d9\u05df \u05d1\u05d0\u05ea\u05e8 \u05db\u05d9 \u05d4\u05de\u05d5\u05e6\u05e8 \u05d0\u05d9\u05e0\u05d5 \u05e7\u05d9\u05d9\u05dd \u05d1\u05de\u05dc\u05d0\u05d9 \u05d0\u05d5 \u05e9\u05d4\u05de\u05d5\u05e6\u05e8 \u05dc\u05d0 \u05d4\u05d5\u05e8\u05d3 \u05de\u05d4\u05d0\u05ea\u05e8 \u05e2\u05d3 \u05dc\u05de\u05d5\u05e2\u05d3 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05dc\u05d0 \u05ea\u05d4\u05d0 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05de\u05d7\u05d5\u05d9\u05d1\u05ea \u05dc\u05e1\u05e4\u05e7 \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05d5\/\u05d0\u05d5 \u05d0\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05dc\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05db\u05dc \u05d8\u05e2\u05e0\u05d4 \u05d5\/\u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d5\/\u05d0\u05d5 \u05ea\u05d1\u05d9\u05e2\u05d4 \u05d1\u05e2\u05e0\u05d9\u05d9\u05df \u05d6\u05d4 \u05d1\u05d2\u05d9\u05df \u05db\u05dc \u05e1\u05d5\u05d2 \u05e9\u05dc \u05e0\u05d6\u05e7, \u05d1\u05d9\u05df \u05e0\u05d6\u05e7 \u05d9\u05e9\u05d9\u05e8 \u05d0\u05d5 \u05e0\u05d6\u05e7 \u05e2\u05e7\u05d9\u05e3 \u05d0\u05e9\u05e8 \u05e0\u05d2\u05e8\u05dd \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d5\/\u05d0\u05d5 \u05dc\u05e6\u05d3 \u05d2'.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d9\u05df \u05d1\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 \u05d6\u05d4 \u05db\u05d3\u05d9 \u05dc\u05d2\u05e8\u05d5\u05e2 \u05de\u05d7\u05d5\u05d1\u05ea\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d4\u