5de\u05d5\u05d6\u05dc.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp;&nbsp;\u003Cstrong\u003E&nbsp;8.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003C\/strong\u003E\u003Cb\u003E\u003Cspan\u003E\u003Cstrong\u003E\u05de\u05e9\u05dc\u003C\/strong\u003E\u05d5\u05d7\u003C\/span\u003E\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;8.1.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05d0\u05d7\u05e8 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05e1\u05e4\u05e7 \u05d0\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05db\u05ea\u05d5\u05d1\u05ea \u05d1\u05d9\u05e9\u05e8\u05d0\u05dc, \u05e9\u05d4\u05d5\u05d6\u05e0\u05d4 \u05d1\u05d8\u05d5\u05e4\u05e1 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.2.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05e4\u05e0\u05d9 \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05ea\u05d9\u05e9\u05dc\u05d7 \u05d4\u05d5\u05d3\u05e2\u05ea SMS.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.3.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05de\u05de\u05d5\u05e2\u05d3 \u05e7\u05d1\u05dc\u05ea \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d7\u05d1\u05e8\u05ea \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9, \u05ea\u05e1\u05e4\u05e7 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05ea \u05de\u05e9\u05dc\u05d5\u05d7 \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d9\u05df 3 \u05dc- 14 \u05d9\u05de\u05d9 \u05e2\u05e1\u05e7\u05d9\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\"\u003Cb\u003E\u05d9\u05de\u05d9 \u05e2\u05e1\u05e7\u05d9\u05dd\u003C\/b\u003E\": \u05d9\u05de\u05d9 \u05d0' \u05e2\u05d3 \u05d4' \u05dc\u05d0 \u05db\u05d5\u05dc\u05dc \u05d9\u05de\u05d9 \u05e9\u05d9\u05e9\u05d9, \u05e9\u05d1\u05ea, \u05e2\u05e8\u05d1\u05d9 \u05d7\u05d2 \u05d5\u05d9\u05de\u05d9 \u05d7\u05d2.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.4.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05e2\u05d3\u05db\u05df \u05d0\u05ea \u05ea\u05e2\u05e8\u05d9\u05e4\u05d9 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7\u05d9\u05dd \u05de\u05e2\u05ea \u05dc\u05e2\u05ea \u05d5\u05d1\u05dc\u05d0 \u05e6\u05d5\u05e8\u05da \u05d1\u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05d5\u05e7\u05d3\u05de\u05ea. \u05ea\u05e2\u05e8\u05d9\u05e4\u05d9 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7\u05d9\u05dd, \u05e2\u05d3 \u05d0\u05e9\u05e8 \u05d9\u05e2\u05d5\u05d3\u05db\u05e0\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9 \u05d5\u05d4\u05de\u05d5\u05d7\u05dc\u05d8, \u05d4\u05d9\u05e0\u05dd \u05db\u05d3\u05dc\u05e7\u05de\u05df:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.4.1.&nbsp; &nbsp; &nbsp; &nbsp;\u05de\u05e9\u05dc\u05d5\u05d7 \u05e2\u05dc-\u05d9\u05d3\u05d9 \u05e9\u05dc\u05d9\u05d7 \u05e2\u05d3 \u05dc\u05d1\u05d9\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7 (\u05dc\u05e4\u05d9 \u05db\u05ea\u05d5\u05d1\u05ea \u05e9\u05ea\u05d9\u05e0\u05ea\u05df \u05d1\u05e4\u05e8\u05d8\u05d9 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d1\u05d0\u05ea\u05e8) \u05d9\u05d4\u05d9\u05d4 \u05d1\u05e1\u05da 29 \u20aa.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05d2\u05d9\u05df \u05e8\u05db\u05d9\u05e9\u05d4 \u05de\u05e2\u05dc 500 \u20aa \u05d9\u05d4\u05d0 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05d7\u05d9\u05e0\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.4.2.&nbsp; &nbsp; &nbsp; &nbsp;\u05e2\u05dc\u05d5\u05ea \u05de\u05e9\u05dc\u05d5\u05d7 \u05dc\u05d0\u05d7\u05d3 \u05de\u05e1\u05e0\u05d9\u05e4\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d4\u05e7\u05e8\u05d5\u05d1\u05d9\u05dd \u05dc\u05d1\u05d9\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d9\u05d4\u05d0 \u05d1\u05d7\u05d9\u05e0\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.4.3.&nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d9\u05e1\u05d5\u05e3 \u05e2\u05e6\u05de\u05d9 \u05e9\u05dc \u05d4\u05de\u05d5\u05e6\u05e8 \u05de\u05de\u05e9\u05e8\u05d3\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05db\u05ea\u05d5\u05d1\u05ea: \u05e8\u05d7' \u05d4\u05d0\u05d5\u05d3\u05dd 12 \u05e4\u05ea\u05d7 \u05ea\u05e7\u05d5\u05d4 \u05d9\u05d4\u05d0 \u05d1\u05d7\u05d9\u05e0\u05dd - \u05d9\u05de\u05d9\u05dd \u05d0-\u05d4 \u05d1\u05e9\u05e2\u05d5\u05ea 9:30 \u05e2\u05d3 15:30.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.5.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05e2\u05dc\u05d5\u05ea \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05d0\u05d9\u05e0\u05d4 \u05db\u05dc\u05d5\u05dc\u05d4 \u05d1\u05de\u05d7\u05d9\u05e8 \u05d4\u05de\u05d5\u05e6\u05e8\/\u05d9\u05dd \u05d5\u05d4\u05d9\u05d0 \u05ea\u05ea\u05d5\u05d5\u05e1\u05e3 \u05dc\u05de\u05d7\u05d9\u05e8 \u05d4\u05db\u05d5\u05dc\u05dc \u05e9\u05dc \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd. \u05ea\u05e2\u05e8\u05d9\u05e3 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05d4\u05d6\u05de\u05e0\u05d4 \u05e9\u05d1\u05d5\u05e6\u05e2\u05d4 \u05d4\u05d5\u05d0 \u05ea\u05e2\u05e8\u05d9\u05e3 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05d1\u05d0\u05ea\u05e8 \u05d1\u05e2\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05dd \u05e2\u05d5\u05d3\u05db\u05e0\u05d5 \u05ea\u05e2\u05e8\u05d9\u05e4\u05d9 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7\u05d9\u05dd \u05d8\u05e8\u05dd \u05d4\u05e9\u05dc\u05de\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05d9\u05d7\u05d5\u05d9\u05d1 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e2\u05e8\u05d9\u05e4\u05d9\u05dd \u05d4\u05de\u05e2\u05d5\u05d3\u05db\u05e0\u05d9\u05dd. \u05e2\u05dc\u05d5\u05ea \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05d4\u05de\u05e2\u05d5\u05d3\u05db\u05e0\u05ea \u05ea\u05e4\u05d5\u05e8\u05e1\u05dd \u05d1\u05d0\u05ea\u05e8 \u05d4\u05d7\u05d1\u05e8\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.6.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d1\u05e6\u05e2 \u05d0\u05ea \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d7\u05d1\u05e8\u05ea \u05e9\u05d9\u05dc\u05d5\u05d7 \u05d0\u05d5 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05e9\u05dc\u05d9\u05d7 \u05de\u05d8\u05e2\u05de\u05d4, \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d7\u05dc\u05d5\u05df \u05d4\u05d6\u05de\u05df \u05e9\u05e0\u05d1\u05d7\u05e8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d1\u05e2\u05ea \u05d4\u05e8\u05db\u05d9\u05e9\u05d4.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.7.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05d9\u05e2\u05d3\u05d9 \u05d0\u05e1\u05e4\u05e7\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\/\u05d9\u05dd \u05d4\u05d9\u05e0\u05dd \u05d1\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05e9\u05d8\u05d7\u05d9 \u05de\u05d3\u05d9\u05e0\u05ea \u05d9\u05e9\u05e8\u05d0\u05dc.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;8.8.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05d0 \u05e1\u05d5\u05e4\u05e7 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05de\u05e1\u05d9\u05d1\u05d4 \u05d4\u05e7\u05e9\u05d5\u05e8\u05d4 \u05d1\u05dc\u05e7\u05d5\u05d7, \u05dc\u05e8\u05d1\u05d5\u05ea \u05d0\u05da \u05de\u05d1\u05dc\u05d9 \u05dc\u05d2\u05e8\u05d5\u05e2, \u05e2\u05e7\u05d1 \u05de\u05e1\u05d9\u05e8\u05ea \u05e4\u05e8\u05d8\u05d9\u05dd \u05e9\u05d2\u05d5\u05d9\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05dc\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d1\u05e2\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4,\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\/\u05d0\u05d5 \u05de\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d0 \u05d4