5dc\u05d0\u05ea\u05e8, \u05e4\u05e2\u05d9\u05dc\u05d5\u05ea\u05d5 \u05d5\u05d0\u05d5\u05e4\u05df \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d6\u05de\u05e0\u05d5\u05ea, \u05e0\u05d9\u05ea\u05df \u05dc\u05e4\u05e0\u05d5\u05ea \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05d0\u05d7\u05d3 \u05de\u05d4\u05d0\u05de\u05e6\u05e2\u05d9\u05dd \u05d4\u05d1\u05d0\u05d9\u05dd:\u003Cbr \/\u003E\u003Cb\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05d8\u05dc\u05e4\u05d5\u05df\u003C\/b\u003E: 6618*\u003Cbr \/\u003E\u003Cb\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05d3\u05d5\u05d0\u05e8 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u003C\/b\u003E: opticana@opticana.co.il\u003Cbr \/\u003E\u003Cb\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05e4\u05d9\u05d9\u05e1\u05d1\u05d5\u05e7 \u05d1\u05e2\u05de\u05d5\u05d3\u003C\/b\u003E: \u05d0\u05d5\u05e4\u05d8\u05d9\u05e7\u05e0\u05d4 OPTICANA\u003Cbr \/\u003E\u003Cb\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05d3\u05d5\u05d0\u05e8:\u003C\/b\u003E&nbsp;\u05dc\u05d9\u05d9\u05d3\u05d9 \u05d0\u05d5\u05e4\u05d8\u05d9\u05e7\u05e0\u05d4 \u05e9\u05d9\u05e8\u05d5\u05ea \u05dc\u05e7\u05d5\u05d7\u05d5\u05ea: \u05d4\u05d0\u05d5\u05d3\u05dd 12, \u05e7\u05e8\u05d9\u05d9\u05ea \u05de\u05d8\u05dc\u05d5\u05df, \u05e4\u05ea\u05d7 \u05ea\u05e7\u05d5\u05d4, \u05de\u05d9\u05e7\u05d5\u05d3 49170.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E\u003Cstrong\u003E&nbsp; &nbsp; &nbsp;10.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003Cspan\u003E\u05d1\u05d9\u05d8\u05d5\u05dc \u05e2\u05e1\u05e7\u05d4\u003C\/span\u003E\u003C\/strong\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;10.1.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05e7\u05d5\u05d7 \u05e9\u05d1\u05d9\u05e6\u05e2 \u05d4\u05d6\u05de\u05e0\u05d4 \u05e8\u05e9\u05d0\u05d9 \u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05e2\u05e1\u05e7\u05d4 \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d7\u05d5\u05e7 \u05d4\u05d2\u05e0\u05ea \u05d4\u05e6\u05e8\u05db\u05df, \u05d4\u05ea\u05e9\u05de\"\u05d0-1981 (\u05dc\u05d4\u05dc\u05df: \"\u003Cb\u003E\u05d7\u05d5\u05e7 \u05d4\u05d2\u05e0\u05ea \u05d4\u05e6\u05e8\u05db\u05df\u003C\/b\u003E\"), \u05d0\u05e9\u05e8 \u05e2\u05d9\u05e7\u05e8\u05d9\u05d4\u05df \u05d9\u05d5\u05d1\u05d0\u05d5 \u05dc\u05d4\u05dc\u05df.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d9\u05d5\u05d1\u05d4\u05e8, \u05db\u05d9 \u05e1\u05e2\u05d9\u05e3 10 \u05d6\u05d4 \u05d9\u05d7\u05d5\u05dc \u05e2\u05dc \"\u05e6\u05e8\u05db\u05df\" \u05db\u05d4\u05d2\u05d3\u05e8\u05ea\u05d5 \u05d1\u05e1\u05e2\u05d9\u05e3 1 \u05dc\u05d7\u05d5\u05e7 \u05d4\u05d2\u05e0\u05ea \u05d4\u05e6\u05e8\u05db\u05df.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.2.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003Cb\u003E\u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05d6\u05de\u05e0\u05d4 \u05e2\"\u05d9 \u05dc\u05e7\u05d5\u05d7&nbsp;\u003Cspan\u003E\u05dc\u05e4\u05e0\u05d9&nbsp;\u003C\/span\u003E\u05e7\u05d1\u05dc\u05ea\u05d4 \u05d0\u05e6\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7\u003C\/b\u003E:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.2.1.&nbsp; &nbsp; &nbsp;\u05db\u05dc \u05e2\u05d5\u05d3 \u05dc\u05d0 \u05e1\u05d5\u05e4\u05e7\u05d4 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d5\u05e2\u05d3 \u05ea\u05d9\u05d0\u05d5\u05dd \u05d4\u05de\u05e9\u05dc\u05d5\u05d7, \u05e8\u05e9\u05d0\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05db\u05d5\u05dc\u05d4 \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d4, \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05d5\u05d3\u05e2\u05d4 \u05d1\u05db\u05ea\u05d1 (\u05dc\u05e8\u05d1\u05d5\u05ea \u05d3\u05d5\u05d0\"\u05dc)&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\/\u05d0\u05d5 \u05d1\u05e2\u05dc \u05e4\u05d4 \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 9 \u05dc\u05e2\u05d9\u05dc, \u05d5\u05db\u05df \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05e7\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d9\u05d9\u05e2\u05d5\u05d3\u05d9 \u05d4\u05de\u05e6\u05d5\u05d9 \u05d1\u05d0\u05ea\u05e8 \u05d5\u05e0\u05e7\u05e8\u05d0: \"\u05e6\u05d5\u05e8 \u05e7\u05e9\u05e8\".\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.2.2.&nbsp; &nbsp; &nbsp;\u05d1\u05d5\u05d8\u05dc\u05d4 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.2 \u05d6\u05d4, \u05ea\u05e9\u05dc\u05d7 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d5\u05d3\u05e2\u05ea \u05d3\u05d5\u05d0\u05e8 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9 \u05d4\u05de\u05d0\u05e9\u05e8\u05ea \u05d6\u05d0\u05ea, \u05d5\u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d7\u05d6\u05d9\u05e8 \u05dc\u05dc\u05e7\u05d5\u05d7, \u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05ea \u05d4\u05d5\u05d3\u05e2\u05ea \u05d4\u05d1\u05d9\u05d8\u05d5\u05dc \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.2.1 \u05dc\u05e2\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05db\u05d5\u05dd \u05e9\u05e9\u05d5\u05dc\u05dd \u05e2\u05dc \u05d9\u05d3\u05d5,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05d0\u05dd \u05d1\u05d7\u05e8 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05e6\u05e2 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d1\u05db\u05e8\u05d8\u05d9\u05e1 \u05d0\u05e9\u05e8\u05d0\u05d9, \u05d1\u05e2\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05d1\u05e0\u05d9\u05db\u05d5\u05d9 \u05d3\u05de\u05d9 \u05d1\u05d9\u05d8\u05d5\u05dc \u05d1\u05e9\u05d9\u05e2\u05d5\u05e8 5% \u05de\u05de\u05d7\u05d9\u05e8 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d0\u05d5 100 \u05e9\u05e7\u05dc\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd, \u05d4\u05e0\u05de\u05d5\u05da \u05de\u05d1\u05d9\u05df \u05d4\u05e9\u05e0\u05d9\u05d9\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.3.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003Cb\u003E\u05d1\u05d9\u05d8\u05d5\u05dc&nbsp;\u003Cspan\u003E\u05dc\u05d0\u05d7\u05e8\u003C\/span\u003E&nbsp;\u05e7\u05d1\u05dc\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d0\u05e6\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7\u003C\/b\u003E:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.3.1.&nbsp; &nbsp; &nbsp;\u05e1\u05d5\u05e4\u05e7\u05d4 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05dc\u05dc\u05e7\u05d5\u05d7, \u05e8\u05e9\u05d0\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05db\u05d5\u05dc\u05d4 \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d4, \u05d1\u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05d9\u05d5\u05dd \u05e9\u05e1\u05d5\u05e4\u05e7\u05d4 \u05dc\u05d5, \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05d5\u05d3\u05e2\u05d4 \u05d1\u05db\u05ea\u05d1 \u05d5\/\u05d0\u05d5 \u05d1\u05e2\u05dc \u05e4\u05d4 \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 9 \u05dc\u05e2\u05d9\u05dc,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05db\u05df \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05e7\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d9\u05d9\u05e2\u05d5\u05d3\u05d9 \u05d4\u05de\u05e6\u05d5\u05d9 \u05d1\u05d0\u05ea\u05e8 \u05d5\u05e0\u05e7\u05e8\u05d0 \"\u05e6\u05d5\u05e8 \u05e7\u05e9\u05e8\". \u05dc\u05de\u05e2\u05df \u05d4\u05e1\u05e8 \u05e1\u05e4\u05e7, \u05dc\u05d0\u05d7\u05e8 14 \u05d9\u05de\u05d9\u05dd \u05de\u05de\u05d5\u05e2\u05d3 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d1\u05d8\u05dc\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.3.2.&nbsp; &nbsp; &nbsp;\u05d1\u05d5\u05d8\u05dc\u05d4 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.3 \u05d6\u05d4, \u05ea\u05d9\u05e9\u05dc\u05d7 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d5\u05d3\u05e2\u05ea \u05d3\u05d5\u05d0\u05e8 \u05dc\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9 \u05d4\u05de\u05d0\u05e9\u05e8\u05ea \u05d0\u05ea \u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05e8\u05db\u05d9\u05e9\u05d4, \u05d5\u05e2\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d4\u05e9\u05d9\u05d1 \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05dc\u05db\u05ea\u05d5\u05d1\u05ea:&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d0\u05d5\u05d3\u05dd 12, \u05e7\u05e8\u05d9\u05d9\u05ea \u05de\u05d8\u05dc\u05d5\u05df, \u05e4\u05ea\u05d7 \u05ea\u05e7\u05d5\u05d4, \u05de\u05d9\u05e7\u05d5\u05d3 49170,\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05ea\u05d5\u05da 7 \u05d9\u05de\u05d9\u05dd \u05de\u05de\u05d5\u05e2\u05d3 \u05de\u05ea\u05df \u05d4\u05d5\u05d3\u05e2\u05ea \u05d4\u05d1\u05d9\u05d8\u05d5\u05dc, \u05d5\u05d1\u05dc\u05d1\u05d3 \u05e9\u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05ea\u05e7\u05d9\u05e0\u05d9\u05dd \u05d5\u05dc\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d4\u05dd \u05e9\u05d9\u05de\u05d5\u05e9, \u05d1\u05d0\u05e8\u05d9\u05d6\u05ea\u05dd \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05ea, \u05db\u05e9\u05d4\u05dd \u05e9\u05dc\u05de\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05dc\u05dc\u05d0 \u05e4\u05d2\u05d9\u05e2\u05d4 \u05d5\/\u05d0\u05d5 \u05e0\u05d6\u05e7 \u05d5\/\u05d0\u05d5 \u05e4\u05d2\u05dd \u05d5\/\u05d0\u05d5 \u05e7\u05dc\u05e7\u05d5\u05dc \u05de\u05db\u05dc \u05de\u05d9\u05df \u05d5\u05e1\u05d5\u05d2.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05de\u05e9\u05e7\u05e4\u05d9 \u05e8\u05d0\u05d9\u05d4 \u05e9\u05d4\u05d5\u05db\u05e0\u05d5 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3. \u05d4\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05d1\u05d2\u05d9\u05df \u05db\u05dc \u05e4\u05d2\u05dd \u05e9\u05d9\u05d9\u05d2\u05e8\u05dd \u05dc\u05de\u05d5\u05e6\u05e8 \u05e2\u05e7\u05d1 \u05d0\u05e8\u05d9\u05d6\u05d4 \u05e8\u05e9\u05dc\u05e0\u05d9\u05ea \u05ea\u05d7\u05d5\u05dc \u05e2\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7. \u05d4\u05d5\u05d0\u05d9\u05dc \u05d5\u05d4\u05de\u05d5\u05e6\u05e8\/\u05d9\u05dd \u05d0\u05d9\u05e0\u05dd \u05e0\u05de\u05db\u05e8\u05d9\u05dd \u05d1\u05d7\u05e0\u05d5\u05d9\u05d5\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d0\u05dc\u05d0 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05d0\u05ea\u05e8 \u05d1\u05dc\u05d1\u05d3,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05e9\u05d1\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05de\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d1\u05d9\u05d8\u05d5\u05dc \u05db\u05d0\u05de\u05d5\u05e8 \u05dc\u05d0 \u05ea\u05d9\u05e2\u05e9\u05d4 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05e9\u05d1\u05ea\u05dd \u05dc\u05d0\u05d7\u05ea \u05de\u05d7\u05e0\u05d5\u05d9\u05d5\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d0\u05dc\u05d0 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05ea\u05d9\u05d0\u05d5\u05dd \u05e9\u05d9\u05dc\u05d5\u05d7 \u05de\u05d5\u05dc \u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05d1\u05dc\u05d1\u05d3.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d9\u05ea\u05e8 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05e1\u05e2\u05d9\u05e3 \u05d6\u05d4 \u05d9\u05d7\u05d5\u05dc\u05d5 \u05e2\u05dc \u05d4\u05e9\u05d1\u05ea \u05de\u05d5\u05e6\u05e8\/\u05d9\u05dd- \u05d1\u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05d4\u05de\u05d7\u05d5\u05d9\u05d1\u05d9\u05dd. \u05dc\u05d0\u05d7\u05e8 \u05e9\u05dc\u05d9\u05d7\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05e2\u05dc\u05d9\u05da \u05dc\u05d4\u05d5\u05d3\u05d9\u05e2 \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05d6\u05d9\u05d4\u05d5\u05d9 \u05e9\u05dc \u05d4\u05d3\u05d5\u05d0\u05e8 \u05d4\u05e8\u05e9\u05d5\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.3.3.&nbsp; &nbsp; &nbsp;\u05d1\u05db\u05e4\u05d5\u05e3 \u05dc\u05e1\u05e2\u05d9\u05e3 10.3.2 \u05dc\u05e2\u05d9\u05dc, \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d7\u05d6\u05d9\u05e8 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05ea \u05d4\u05d5\u05d3\u05e2\u05ea \u05d4\u05d1\u05d9\u05d8\u05d5\u05dc \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.3.1 \u05dc\u05e2\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05db\u05d5\u05dd \u05e9\u05e9\u05d5\u05dc\u05dd \u05e2\u05dc \u05d9\u05d3\u05d5 \u05d1\u05e2\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05e0\u05d9\u05db\u05d5\u05d9 \u05d3\u05de\u05d9 \u05d1\u05d9\u05d8\u05d5\u05dc \u05d1\u05e9\u05d9\u05e2\u05d5\u05e8 5% \u05de\u05de\u05d7\u05d9\u05e8 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d0\u05d5 100 \u05e9\u05e7\u05dc\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd, \u05d4\u05e0\u05de\u05d5\u05da \u05de\u05d1\u05d9\u05df \u05d4\u05e9\u05e0\u05d9\u05d9\u05dd. \u05d4\u05d4\u05d7\u05d6\u05e8, \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.3 \u05d6\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d9\u05d9\u05e2\u05e9\u05d4 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d6\u05d9\u05db\u05d5\u05d9 \u05db\u05e8\u05d8\u05d9\u05e1 \u05d4\u05d0\u05e9\u05e8\u05d0\u05d9 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea\u05d5 \u05d1\u05d5\u05e6\u05e2\u05d4 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d5\/\u05d0\u05d5 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d6\u05d9\u05db\u05d5\u05d9 \u05d7\u05e9\u05d1\u05d5\u05df \u05d4- PAYPAL \u05e9\u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea\u05d5 \u05d1\u05d5\u05e6\u05e2\u05d4 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05db\u05dc-\u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd \u05d1\u05d5 \u05d1\u05d5\u05e6\u05e2\u05d4 \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05e9\u05d1\u05d5\u05d8\u05dc\u05d4 \u05d5\u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d4\u05e1\u05db\u05de\u05d5\u05ea \u05d1\u05d9\u05df \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d7\u05d1\u05e8\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.3.4.&nbsp; &nbsp; &nbsp;\u05dc\u05de\u05e2\u05df \u05d4\u05e1\u05e8 \u05e1\u05e4\u05e7 \u05de\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d1\u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05d6\u05de\u05e0\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.3 \u05d6\u05d4 \u05dc\u05d0 \u05d9\u05d4\u05d9\u05d4 \u05d6\u05db\u05d0\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d4\u05d7\u05d6\u05e8 \u05d3\u05de\u05d9 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05db\u05db\u05dc \u05e9\u05e9\u05d5\u05dc\u05de\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.4.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003Cb\u003E\u05d1\u05d9\u05d8\u05d5\u05dc \u05d0\u05d5 \u05d4\u05d7\u05dc\u05e4\u05d4 \u05e9\u05dc \u05de\u05d5\u05e6\u05e8 \u05db\u05ea\u05d5\u05e6\u05d0\u05d4&nbsp;\u003Cspan\u003E\u05de\u05e4\u05d2\u05dd \u05d0\u05d5 \u05d0\u05d9 \u05d4\u05ea\u05d0\u05de\u05d4\u003C\/span\u003E&nbsp;\u05dc\u05e4\u05e8\u05d8\u05d9\u05dd \u05d4\u05de\u05d5\u05e4\u05d9\u05e2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8:\u003Cbr \/\u003E\u003C\/b\u003E&nbsp; &nbsp; &nbsp;10.4.1.&nbsp; &nbsp; &nbsp;\u05e2\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05e4\u05e8\u05d9\u05d8\u05d9\u05dd \u05d4\u05db\u05dc\u05d5\u05dc\u05d9\u05dd \u05d1\u05d4\u05d6\u05de\u05e0\u05d4 \u05de\u05d9\u05d3 \u05e2\u05dd \u05e7\u05d1\u05dc\u05ea \u05d4\u05de\u05e9\u05dc\u05d5\u05d7. \u05d4\u05d9\u05d4 \u05d5\u05d4\u05dc\u05e7\u05d5\u05d7 \u05e7\u05d9\u05d1\u05dc \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05db\u05e9\u05d4\u05d5\u05d0 \u05e4\u05d2\u05d5\u05dd, \u05d0\u05d5 \u05db\u05d0\u05e9\u05e8 \u05de\u05e4\u05e8\u05d8 \u05d4\u05de\u05d5\u05e6\u05e8 \u05e9\u05d5\u05e0\u05d4 \u05de\u05d4\u05de\u05e4\u05e8\u05d8 \u05e9\u05e4\u05d5\u05e8\u05e1\u05dd \u05d1\u05d0\u05ea\u05e8,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05e2\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05e4\u05e0\u05d5\u05ea \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d5 \u05d1\u05e2\u05dc \u05e4\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 9 \u05dc\u05e2\u05d9\u05dc, \u05d1\u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05ea \u05d4\u05de\u05d5\u05e6\u05e8.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05db\u05dc \u05e9\u05d9\u05d5\u05d7\u05dc\u05d8 \u05e2\u05dc \u05d9\u05d3\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05e2\u05dc \u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9 \u05d5\u05d4\u05de\u05d5\u05d7\u05dc\u05d8, \u05db\u05d9 \u05d4\u05de\u05d5\u05e6\u05e8 \u05e4\u05d2\u05d5\u05dd, \u05d9\u05d5\u05d7\u05dc\u05e3 \u05d4\u05de\u05d5\u05e6\u05e8 \u05d0\u05d5 \u05ea\u05d1\u05d5\u05d8\u05dc \u05e8\u05db\u05d9\u05e9\u05ea\u05d5, \u05e2\u05dc \u05e4\u05d9 \u05d1\u05d7\u05d9\u05e8\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.4.2.&nbsp; &nbsp; &nbsp;\u05d1\u05de\u05e7\u05e8\u05d4 \u05d1\u05d5 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05de\u05d1\u05e7\u05e9 \u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05e8\u05db\u05d9\u05e9\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05e4\u05d2\u05d5\u05dd, \u05d9\u05d7\u05d5\u05dc\u05d5 \u05d4\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05d1\u05d0\u05d5\u05ea:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.4.2.1.&nbsp; \u05dc\u05dc\u05e7\u05d5\u05d7 \u05ea\u05d9\u05e9\u05dc\u05d7 \u05d4\u05d5\u05d3\u05e2\u05ea \u05d3\u05d5\u05d0\u05e8 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9 \u05d4\u05de\u05d0\u05e9\u05e8\u05ea \u05d0\u05ea \u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05e8\u05db\u05d9\u05e9\u05d4, \u05d5\u05d4\u05d7\u05d1\u05e8\u05d4 \u05d5\/\u05d0\u05d5 \u05de\u05d9 \u05de\u05d8\u05e2\u05de\u05d4 \u05d9\u05d9\u05e6\u05e8\u05d5 \u05e7\u05e9\u05e8 \u05e2\u05dd \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05e9\u05dd \u05ea\u05d9\u05d0\u05d5\u05dd \u05d0\u05d9\u05e1\u05d5\u05e3 \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05e4\u05d2\u05d5\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.4.2.2.&nbsp; \u05d4\u05d5\u05e9\u05d1 \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05e4\u05d2\u05d5\u05dd \u05d0\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4, \u05ea\u05d7\u05d6\u05d9\u05e8 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05dc\u05e7\u05d5\u05d7, \u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05ea \u05d4\u05d5\u05d3\u05e2\u05ea \u05d4\u05d1\u05d9\u05d8\u05d5\u05dc \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.4.1 \u05dc\u05e2\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05db\u05d5\u05dd \u05e9\u05e9\u05d5\u05dc\u05dd \u05e2\u05dc \u05d9\u05d3\u05d5 \u05e2\u05d1\u05d5\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d5\u05e6\u05e8 \u05e4\u05d2\u05d5\u05dd.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d1\u05de\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d1\u05d9\u05d8\u05d5\u05dc \u05de\u05d7\u05de\u05ea \u05e4\u05d2\u05dd, \u05ea\u05d7\u05d6\u05d9\u05e8 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d0\u05ea \u05d3\u05de\u05d9 \u05d4\u05de\u05e9\u05dc\u05d5\u05d7, \u05db\u05db\u05dc \u05e9\u05e9\u05d5\u05dc\u05de\u05d5 \u05e2\u05dc \u05d9\u05d3\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.4.3.&nbsp; &nbsp; &nbsp;\u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05d6\u05de\u05e0\u05d4, \u05d0\u05e3 \u05d0\u05dd \u05e0\u05e2\u05e9\u05d4 \u05de\u05d7\u05de\u05ea \u05e4\u05d2\u05dd \u05d1\u05de\u05d5\u05e6\u05e8, \u05dc\u05d0\u05d7\u05e8 \u05e9\u05e1\u05d5\u05e4\u05e7\u05d4 \u05dc\u05dc\u05e7\u05d5\u05d7, \u05db\u05e4\u05d5\u05e3 \u05dc\u05d4\u05e9\u05d1\u05ea \u05d4\u05e4\u05e8\u05d9\u05d8\u05d9\u05dd \u05e9\u05d4\u05d6\u05de\u05e0\u05ea\u05dd \u05d1\u05d5\u05d8\u05dc\u05d4 \u05dc\u05d7\u05d1\u05e8\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05d0\u05e9\u05e8 \u05dc\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d4\u05dd \u05e9\u05d9\u05de\u05d5\u05e9, \u05d1\u05d0\u05e8\u05d9\u05d6\u05ea\u05dd \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05ea, \u05db\u05e9\u05d4\u05dd \u05e9\u05dc\u05de\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05dc\u05dc\u05d0 \u05e4\u05d2\u05d9\u05e2\u05d4 \u05d5\/\u05d0\u05d5 \u05e0\u05d6\u05e7 \u05d5\/\u05d0\u05d5 \u05e4\u05d2\u05dd \u05d5\/\u05d0\u05d5 \u05e7\u05dc\u05e7\u05d5\u05dc \u05de\u05db\u05dc \u05de\u05d9\u05df \u05d5\u05e1\u05d5\u05d2.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.5.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003Cb\u003E\u05d4\u05d7\u05dc\u05e4\u05ea \u05de\u05d5\u05e6\u05e8\u05d9\u05dd&nbsp;\u003Cspan\u003E\u05e9\u05dc\u05d0 \u05de\u05d7\u05de\u05ea \u05e4\u05d2\u05dd\u003Cbr \/\u003E\u003C\/span\u003E\u003C\/b\u003E&nbsp; &nbsp; &nbsp;10.5.1.&nbsp; &nbsp; &nbsp;\u05dc\u05e7\u05d5\u05d7 \u05d4\u05de\u05e2\u05d5\u05e0\u05d9\u05d9\u05df&nbsp;\u003Cb\u003E\u05dc\u05d4\u05d7\u05dc\u05d9\u05e3\u003C\/b\u003E&nbsp;\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05e9\u05e7\u05d9\u05d1\u05dc \u05d1\u05d4\u05d6\u05de\u05e0\u05d4 \u05e9\u05dc\u05d0 \u05de\u05d7\u05de\u05ea \u05e4\u05d2\u05dd \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 10.5 \u05dc\u05e2\u05d9\u05dc, \u05de\u05ea\u05d1\u05e7\u05e9 \u05dc\u05e4\u05e0\u05d5\u05ea \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 9 \u05dc\u05e2\u05d9\u05dc,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05e2\u05dc \u05de\u05e0\u05ea \u05dc\u05e7\u05d1\u05dc \u05de\u05d9\u05d3\u05e2 \u05db\u05d9\u05e6\u05d3 \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05e1\u05e0\u05d9\u05e3 \u05d9\u05d5\u05db\u05dc \u05dc\u05d4\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05d8\u05e2\u05d5\u05df \u05d4\u05d7\u05dc\u05e4\u05d4. \u05d4\u05d5\u05d0\u05d9\u05dc \u05d5\u05de\u05d5\u05e6\u05e8\/\u05d9\u05dd \u05dc\u05d0 \u05e0\u05de\u05db\u05e8\u05d9\u05dd \u05d1\u05d7\u05e0\u05d5\u05d9\u05d5\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4, \u05d0\u05dc\u05d0 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05d0\u05ea\u05e8 \u05d1\u05dc\u05d1\u05d3,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05dc\u05e4\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05d8\u05e2\u05d5\u05df \u05d4\u05d7\u05dc\u05e4\u05d4 \u05dc\u05d0 \u05ea\u05d1\u05d5\u05e6\u05e2 \u05d1\u05d0\u05d7\u05d3 \u05de\u05d4\u05e1\u05e0\u05d9\u05e4\u05d9\u05dd, \u05d0\u05dc\u05d0 \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d4\u05e0\u05d7\u05d9\u05d5\u05ea \u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05d1\u05dc\u05d1\u05d3.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.5.2.&nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05dc\u05e4\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05db\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 \u05d6\u05d4 \u05ea\u05e2\u05e9\u05d4 \u05d1\u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05d9\u05d5\u05dd \u05e7\u05d1\u05dc\u05ea \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05e2\"\u05d9 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d5\u05d1\u05ea\u05e0\u05d0\u05d9 \u05e9\u05dc\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d4\u05dd \u05e9\u05d9\u05de\u05d5\u05e9, \u05d1\u05d0\u05e8\u05d9\u05d6\u05ea\u05dd \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05ea \u05d5\u05e9\u05d4\u05ea\u05d5\u05d5\u05d9\u05ea\/ \u05ea\u05d2\u05d9\u05ea \u05e2\u05d3\u05d9\u05d9\u05df \u05e6\u05de\u05d5\u05d3\u05d4 \u05dc\u05e4\u05e8\u05d9\u05d8,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05e9\u05d4\u05dd \u05e9\u05dc\u05de\u05d9\u05dd \u05d5\/\u05d0\u05d5 \u05dc\u05dc\u05d0 \u05e4\u05d2\u05d9\u05e2\u05d4 \u05d5\/\u05d0\u05d5 \u05e0\u05d6\u05e7 \u05d5\/\u05d0\u05d5 \u05e4\u05d2\u05dd \u05d5\/\u05d0\u05d5 \u05e7\u05dc\u05e7\u05d5\u05dc \u05de\u05db\u05dc \u05de\u05d9\u05df \u05d5\u05e1\u05d5\u05d2.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.5.3.&nbsp; &nbsp; &nbsp;\u05de\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d4\u05d7\u05dc\u05e4\u05ea \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05d9\u05e0\u05d5 \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05de\u05dc\u05d0\u05d9 \u05d4\u05e7\u05d9\u05d9\u05dd \u05d1\u05d7\u05e0\u05d5\u05ea.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.6.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003Cb\u003E\u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05d6\u05de\u05e0\u05d4 \u05e2\"\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4\u003C\/b\u003E:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.6.1.&nbsp; &nbsp; &nbsp;\u05d1\u05db\u05dc \u05de\u05e7\u05e8\u05d4 \u05d0\u05e9\u05e8 \u05d1\u05d5 \u05e0\u05d1\u05e6\u05e8 \u05d9\u05d4\u05d0 \u05de\u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05e0\u05d4\u05dc \u05d0\u05ea \u05d4\u05d0\u05ea\u05e8 \u05db\u05ea\u05d9\u05e7\u05e0\u05d5, \u05dc\u05e1\u05e4\u05e7 \u05d0\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d0\u05d5 \u05dc\u05e2\u05de\u05d5\u05d3 \u05d1\u05d4\u05ea\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05d0\u05d7\u05e8\u05ea \u05e9\u05dc\u05d4 \u05e2\u05dc \u05e4\u05d9 \u05ea\u05e7\u05e0\u05d5\u05df \u05d6\u05d4, \u05ea\u05d4\u05d0 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea, \u05e2\u05dc \u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9 \u05d5\u05d4\u05de\u05d5\u05d7\u05dc\u05d8,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05d6\u05de\u05e0\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7, \u05d5\u05d1\u05de\u05e7\u05e8\u05d4 \u05db\u05d0\u05de\u05d5\u05e8 \u05ea\u05d9\u05e9\u05dc\u05d7 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d4\u05d5\u05d3\u05e2\u05d4 \u05e2\u05dc \u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05d4\u05d6\u05de\u05e0\u05d4, \u05d5\u05d4\u05ea\u05de\u05d5\u05e8\u05d4 \u05ea\u05d5\u05d7\u05d6\u05e8 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d1\u05ea\u05d5\u05da 14 \u05d9\u05de\u05d9\u05dd \u05de\u05de\u05ea\u05df \u05d4\u05d4\u05d5\u05d3\u05e2\u05d4, \u05d5\u05d4\u05dc\u05e7\u05d5\u05d7 \u05de\u05d5\u05d5\u05ea\u05e8 \u05d1\u05d6\u05d0\u05ea \u05e2\u05dc \u05db\u05dc \u05d8\u05e2\u05e0\u05d4 \u05d5\/\u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d5\/\u05d0\u05d5 \u05ea\u05d1\u05d9\u05e2\u05d4 \u05d1\u05e2\u05e0\u05d9\u05d9\u05df.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;10.7.&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003Cb\u003E\u05de\u05d5\u05d1\u05d4\u05e8 \u05d1\u05d6\u05d0\u05ea \u05db\u05d9 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d7\u05d5\u05e7 \u05d4\u05d2\u05e0\u05ea \u05d4\u05e6\u05e8\u05db\u05df, \u05d4\u05ea\u05e9\u05de\"\u05d0-1981 \u05d4\u05d7\u05dc\u05d5\u05ea \u05d5\u05d4\u05ea\u05e7\u05e4\u05d5\u05ea \u05d1\u05de\u05d5\u05e2\u05d3 \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d4\u05df \u05d4\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05de\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05d0\u05e3 \u05d0\u05dd \u05d1\u05ea\u05e7\u05e0\u05d5\u05df \u05d6\u05d4 \u05d0\u05d5 \u05d1\u05d0\u05ea\u05e8 \u05e8\u05e9\u05d5\u05dd \u05d0\u05d7\u05e8\u05ea.\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;\u003Cstrong\u003E11.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003C\/strong\u003E\u003Cb\u003E\u003Cspan\u003E\u003Cstrong\u003E\u05de\u05e7\u05e8\u05d9\u05dd \u05d1\u05d4\u05dd \u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05e7\u05d1\u05dc \u05d4\u05d7\u05d6\u05e8\u003C\/strong\u003E&nbsp;\u05db\u05e1\u05e4\u05d9\u003C\/span\u003E\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E\u003Cb\u003E\u003Cspan\u003E\u003C\/span\u003E\u003C\/b\u003E&nbsp; &nbsp; &nbsp;11.1.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05e7\u05d1\u05dc \u05d4\u05d7\u05d6\u05e8 \u05db\u05e1\u05e4\u05d9 \u05d1\u05e7\u05e0\u05d9\u05d9\u05ea \u05de\u05d5\u05e6\u05e8 \u05e9\u05d4\u05d5\u05db\u05df \u05d1\u05d4\u05ea\u05d0\u05de\u05d4 \u05d0\u05d9\u05e9\u05d9\u05ea \u05dc\u05dc\u05e7\u05d5\u05d7, \u05db\u05d2\u05d5\u05df: \u05de\u05e9\u05e7\u05e4\u05d9 \u05e8\u05d0\u05d9\u05d4, \u05de\u05e9\u05e7\u05e4\u05d9 \u05e9\u05de\u05e9 \u05d0\u05d5\u05e4\u05d8\u05d9\u05d5\u05ea, \u05de\u05e9\u05e7\u05e4\u05d9 \u05e9\u05de\u05e9 \u05e9\u05d1\u05d5\u05e6\u05e2\u05d4 \u05d1\u05d4\u05dd \u05d4\u05ea\u05d0\u05de\u05d4, \u05e2\u05d3\u05e9\u05d5\u05ea \u05de\u05d2\u05e2 \u05e9\u05d9\u05d5\u05e6\u05e8\u05d5 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05dc\u05dc\u05e7\u05d5\u05d7 (\u05e7\u05d1\u05d5\u05e2\u05d5\u05ea, \u05e7\u05e9\u05d5\u05ea).\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;11.2.&nbsp; &nbsp; &nbsp; &nbsp; \u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05e4\u05e6\u05dc \u05d0\u05d5 \u05dc\u05d1\u05d8\u05dc, \u05d0\u05d5 \u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05e9\u05e0\u05e8\u05db\u05e9\u05d5 \u05d1\u05e2\u05e1\u05e7\u05d0\u05d5\u05ea \u05de\u05e9\u05d5\u05dc\u05d1\u05d5\u05ea \u05db\u05d2\u05d5\u05df &ndash; \"\u003Cb\u003E\u05e7\u05e0\u05d4 \u05e7\u05d1\u05dc\u003C\/b\u003E\" \u05d0\u05d5 \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05e9\u05dc \"\u003Cb\u003E1+1\u003C\/b\u003E\". \u05d1\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d1\u05d0\u05d7\u05ea \u05de\u05d4\u05e9\u05ea\u05d9\u05d9\u05dd:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05d1\u05d8\u05dc\/ \u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05e2\u05e1\u05e7\u05d4 \u05d0\u05d5 \u05dc\u05d0 \u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05e2\u05e1\u05e7\u05d4 \u05d4\u05de\u05e9\u05d5\u05dc\u05d1\u05ea \u05db\u05dc\u05dc.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;\u003Cstrong\u003E12.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003Cspan\u003E\u05e9\u05d9\u05e4\u05d5\u05d9\u003C\/span\u003E\u003C\/strong\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;12.1.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05de\u05ea\u05d7\u05d9\u05d9\u05d1 \u05dc\u05e9\u05e4\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4, \u05e2\u05d5\u05d1\u05d3\u05d9\u05d4, \u05de\u05e0\u05d4\u05dc\u05d9\u05d4 \u05d0\u05d5 \u05de\u05d9 \u05de\u05d8\u05e2\u05de\u05d4 \u05d1\u05d2\u05d9\u05df \u05db\u05dc \u05e0\u05d6\u05e7, \u05d4\u05e4\u05e1\u05d3, \u05d0\u05d1\u05d3\u05df-\u05e8\u05d5\u05d5\u05d7, \u05ea\u05e9\u05dc\u05d5\u05dd \u05d0\u05d5 \u05d4\u05d5\u05e6\u05d0\u05d4 \u05e9\u05d9\u05d9\u05d2\u05e8\u05de\u05d5 \u05dc\u05d4\u05dd- \u05d5\u05d1\u05db\u05dc\u05dc \u05d6\u05d4 \u05e9\u05db\"\u05d8 \u05e2\u05d5\"\u05d3 \u05d5\u05d4\u05d5\u05e6\u05d0\u05d5\u05ea \u05de\u05e9\u05e4\u05d8- \u05e2\u05e7\u05d1 \u05d4\u05e4\u05e8\u05ea \u05ea\u05e7\u05e0\u05d5\u05df \u05d6\u05d4.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;\u003Cstrong\u003E13.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003Cspan\u003E\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05d5\u05e9\u05d9\u05e8\u05d5\u05ea\u003C\/span\u003E\u003C\/strong\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;13.1.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d5\/\u05d0\u05d5 \u05de\u05d9 \u05de\u05d8\u05e2\u05de\u05d4 \u05dc\u05d0 \u05d9\u05d4\u05d9\u05d5 \u05d0\u05d7\u05e8\u05d0\u05d9\u05dd \u05d5\u05dc\u05d0 \u05d9\u05d9\u05e9\u05d0\u05d5 \u05d1\u05db\u05dc \u05e0\u05d6\u05e7 \u05de\u05db\u05dc \u05de\u05d9\u05df \u05d5\u05e1\u05d5\u05d2 \u05e9\u05d4\u05d5\u05d0, \u05d9\u05e9\u05d9\u05e8, \u05e2\u05e7\u05d9\u05e3, \u05ea\u05d5\u05e6\u05d0\u05ea\u05d9 \u05d0\u05d5 \u05de\u05d9\u05d5\u05d7\u05d3, \u05e9\u05d9\u05d2\u05e8\u05dd \u05dc\u05de\u05e9\u05ea\u05de\u05e9 \u05d5\/\u05d0\u05d5 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d5\/\u05d0\u05d5 \u05dc\u05e6\u05d3 \u05e9\u05dc\u05d9\u05e9\u05d9, \u05db\u05ea\u05d5\u05e6\u05d0\u05d4 \u05de\u05e9\u05d9\u05de\u05d5\u05e9 \u05d5\/\u05d0\u05d5 \u05d4\u05d6\u05de\u05e0\u05d4 \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea \u05d4\u05d0\u05ea\u05e8 -&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05ea\u05d4\u05d0 \u05e2\u05d9\u05dc\u05ea \u05d4\u05ea\u05d1\u05d9\u05e2\u05d4 \u05d0\u05e9\u05e8 \u05ea\u05d4\u05d0 - \u05dc\u05e8\u05d1\u05d5\u05ea \u05d4\u05e4\u05e1\u05d3 \u05d4\u05db\u05e0\u05e1\u05d4 \u05d5\/\u05d0\u05d5 \u05de\u05e0\u05d9\u05e2\u05ea \u05e8\u05d5\u05d5\u05d7 \u05e9\u05d9\u05d2\u05e8\u05de\u05d5 \u05de\u05db\u05dc \u05e1\u05d9\u05d1\u05d4 \u05e9\u05d4\u05d9\u05d0.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.2.&nbsp; &nbsp; &nbsp; &nbsp; \u05e0\u05e4\u05dc\u05d4 \u05d8\u05e2\u05d5\u05ea \u05e7\u05d5\u05dc\u05de\u05d5\u05e1 \u05d1\u05ea\u05d9\u05d0\u05d5\u05e8 \u05d4\u05e6\u05d1\u05e2 \u05d5\/\u05d0\u05d5 \u05d1\u05e0\u05e8\u05d0\u05d5\u05ea \u05d4\u05e6\u05d1\u05e2, \u05d5\/\u05d0\u05d5 \u05d1\u05d0\u05d5\u05e4\u05df \u05d1\u05d5 \u05e0\u05e8\u05d0\u05d4 \u05d4\u05e6\u05d1\u05e2 \u05d1\u05de\u05e1\u05da \u05d4\u05de\u05e9\u05ea\u05de\u05e9, \u05dc\u05d0 \u05d9\u05d7\u05d9\u05d9\u05d1 \u05d4\u05d3\u05d1\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05e7\u05d8\u05dc\u05d5\u05d2 \u05d4\u05e6\u05d1\u05e2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05e0\u05d5\u05e2\u05d3 \u05dc\u05d4\u05de\u05d7\u05e9\u05d4 \u05d1\u05dc\u05d1\u05d3 \u05d5\u05d9\u05d9\u05ea\u05db\u05e0\u05d5 \u05d4\u05d1\u05d3\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05e6\u05d1\u05e2\u05d9\u05dd \u05d4\u05de\u05d5\u05e6\u05d2\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8, \u05d7\u05dc\u05e7\u05df \u05d0\u05d5 \u05db\u05d5\u05dc\u05df, \u05dc\u05d1\u05d9\u05df \u05d4\u05e6\u05d1\u05e2\u05d9\u05dd \u05d4\u05e0\u05de\u05db\u05e8\u05d9\u05dd \u05d1\u05e4\u05d5\u05e2\u05dc.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.3.&nbsp; &nbsp; &nbsp; &nbsp; \u05ea\u05de\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05e0\u05d5\u05e2\u05d3\u05d5 \u05dc\u05d4\u05de\u05d7\u05e9\u05d4 \u05d1\u05dc\u05d1\u05d3, \u05d5\u05d0\u05d9\u05e0\u05dd \u05de\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d1\u05e8\u05d4. \u05de\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05d9\u05d9\u05ea\u05db\u05e0\u05d5 \u05d4\u05d1\u05d3\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05ea\u05de\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05d5\u05e6\u05d2\u05d5\u05ea \u05d1\u05d0\u05ea\u05e8, \u05d7\u05dc\u05e7\u05df \u05d0\u05d5 \u05db\u05d5\u05dc\u05df, \u05dc\u05d1\u05d9\u05df \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d4\u05e0\u05de\u05db\u05e8\u05d9\u05dd \u05d1\u05e4\u05d5\u05e2\u05dc,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05d4\u05dc\u05e7\u05d5\u05d7 \u05de\u05d5\u05d5\u05ea\u05e8 \u05d1\u05d6\u05d0\u05ea \u05e2\u05dc \u05db\u05dc \u05d8\u05e2\u05e0\u05d4 \u05d5\/\u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d5\/\u05d0\u05d5 \u05ea\u05d1\u05d9\u05e2\u05d4 \u05d1\u05e2\u05e0\u05d9\u05d9\u05df \u05d6\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.4.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e2\u05d5\u05e9\u05d4 \u05db\u05db\u05dc \u05e9\u05d1\u05d9\u05db\u05d5\u05dc\u05ea\u05d4 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05de\u05d5\u05e6\u05d2 \u05d1\u05d0\u05ea\u05e8 \u05d9\u05d4\u05d9\u05d4 \u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05e9\u05dc\u05dd \u05d5\u05d4\u05de\u05d3\u05d5\u05d9\u05e7 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d0\u05da \u05d9\u05d5\u05d1\u05d4\u05e8, \u05db\u05d9 \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d5, \u05d1\u05ea\u05d5\u05dd \u05dc\u05d1,\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05d9 \u05d3\u05d9\u05d5\u05e7\u05d9\u05dd \u05d0\u05d5 \u05e9\u05d2\u05d9\u05d0\u05d5\u05ea \u05d0\u05e9\u05e8 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d1\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05db\u05dc\u05e9\u05d4\u05d9 \u05d4\u05e0\u05d5\u05d1\u05e2\u05ea \u05de\u05d4\u05dd \u05d0\u05d5 \u05e7\u05e9\u05d5\u05e8\u05d4 \u05d0\u05dc\u05d9\u05d4\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.5.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05de\u05e1\u05db\u05d9\u05de\u05d9\u05dd \u05db\u05d9 \u05d1\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea\u05dd \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d5\u05dc\u05d4\u05e2\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05d0\u05ea\u05e8 \u05d5\u05d4\u05ea\u05d5\u05db\u05df, \u05d5\u05db\u05d9 \u05d4\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05dc\u05db\u05dc \u05e1\u05d9\u05db\u05d5\u05df \u05d0\u05e9\u05e8 \u05e2\u05e9\u05d5\u05d9 \u05dc\u05d4\u05d9\u05d2\u05e8\u05dd \u05dc\u05de\u05e9\u05ea\u05de\u05e9 \u05db\u05ea\u05d5\u05e6\u05d0\u05d4 \u05de\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8 \u05d5\/\u05d0\u05d5 \u05d1\u05ea\u05d5\u05db\u05df, \u05db\u05d5\u05dc\u05d5 \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d5, \u05dc\u05e8\u05d1\u05d5\u05ea, \u05d0\u05da \u05dc\u05d0 \u05e8\u05e7,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05dc \u05d4\u05d7\u05dc\u05d8\u05d4 \u05e9\u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05e2\u05e9\u05d5\u05d9 \u05dc\u05e7\u05d1\u05dc \u05d1\u05d4\u05ea\u05d1\u05e1\u05e1 \u05e2\u05dc \u05d4\u05d3\u05d9\u05d5\u05e7, \u05d4\u05e9\u05dc\u05de\u05d5\u05ea, \u05d4\u05d0\u05de\u05d9\u05e0\u05d5\u05ea, \u05d5\u05d4\u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05ea\u05d5\u05db\u05df, \u05de\u05d5\u05d8\u05dc\u05ea \u05e2\u05dc\u05d9\u05d4\u05dd \u05d1\u05dc\u05d1\u05d3. \u05e0\u05d1\u05d4\u05d9\u05e8 \u05db\u05d9 \u05e0\u05e1\u05d9\u05d1\u05d5\u05ea \u05d0\u05d9\u05e9\u05d9\u05d5\u05ea \u05de\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05d4\u05ea\u05d9\u05d9\u05d7\u05e1\u05d5\u05ea \u05d0\u05d9\u05e9\u05d9\u05ea \u05e9\u05dc \u05d1\u05e2\u05dc \u05de\u05e7\u05e6\u05d5\u05e2.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05e7\u05d5\u05d7 \u05d1\u05db\u05dc \u05e0\u05e1\u05d9\u05d1\u05d5\u05ea \u05d0\u05d9\u05e9\u05d9\u05d5\u05ea \u05de\u05ea\u05d1\u05e7\u05e9 \u05dc\u05e4\u05e0\u05d5\u05ea \u05dc\u05d1\u05e2\u05dc \u05de\u05e7\u05e6\u05d5\u05e2 \u05de\u05ea\u05d0\u05d9\u05dd \u05db\u05d2\u05d5\u05df \u05e8\u05d5\u05e4\u05d0 \u05e2\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d0\u05d5\u05e4\u05d8\u05d5\u05de\u05d8\u05e8\u05d9\u05e1\u05d8 \u05d5\u05db\u05d5' \u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05de\u05d4\u05dc\u05da \u05d4\u05de\u05e1\u05ea\u05de\u05da \u05e2\u05dc \u05d4\u05de\u05d9\u05d3\u05e2 \u05d1\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.6.&nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05db\u05dc \u05de\u05e7\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05db\u05dc\u05e9\u05d4\u05d9 \u05dc\u05d2\u05d1\u05d9 \u05e0\u05d6\u05e7 \u05e9\u05d0\u05d9\u05e0\u05d5 \u05d9\u05e9\u05d9\u05e8. \u05dc\u05d2\u05d1\u05d9 \u05e0\u05d6\u05e7 \u05d9\u05e9\u05d9\u05e8, \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05d4\u05e2\u05d5\u05dc\u05d4 \u05e2\u05dc \u05d4\u05e1\u05db\u05d5\u05dd \u05e9\u05e9\u05d5\u05dc\u05dd \u05d1\u05d2\u05d9\u05df \u05d4\u05de\u05e9\u05e7\u05e4\u05d9\u05d9\u05dd\/ \u05d4\u05de\u05d5\u05e6\u05e8 \u05d4\u05e0\u05e8\u05db\u05e9.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05db\u05dc \u05d4\u05d0\u05de\u05d5\u05e8 \u05dc\u05e2\u05d9\u05dc, \u05de\u05d1\u05dc\u05d9 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05d6\u05db\u05d5\u05ea\u05d5 \u05e9\u05dc \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05dc\u05e7\u05d1\u05dc \u05d4\u05e9\u05d1\u05d4 \u05e9\u05dc \u05db\u05dc \u05ea\u05e9\u05dc\u05d5\u05dd \u05e9\u05e9\u05d9\u05dc\u05dd \u05dc\u05d7\u05d1\u05e8\u05d4 \u05d1\u05d0\u05dd \u05d1\u05d9\u05ea \u05d4\u05de\u05e9\u05e4\u05d8 \u05d4\u05de\u05d5\u05e1\u05de\u05da \u05d9\u05e7\u05d1\u05e2 \u05db\u05d9 \u05d4\u05d5\u05d0 \u05d6\u05db\u05d0\u05d9 \u05dc\u05d4\u05e9\u05d1\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.7.&nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05db\u05dc \u05de\u05e7\u05e8\u05d4 \u05e9\u05dc \u05ea\u05d1\u05d9\u05e2\u05d4, \u05de\u05db\u05dc \u05de\u05d9\u05df \u05d5\u05e1\u05d5\u05d2, \u05d1\u05db\u05dc \u05d4\u05e7\u05e9\u05d5\u05e8, \u05d4\u05db\u05e8\u05d5\u05da \u05d5\u05d4\u05e0\u05d5\u05d1\u05e2 \u05de\u05d0\u05ea\u05e8 \u05d6\u05d4 \u05d9\u05d5\u05d2\u05d1\u05dc \u05de\u05d5\u05e2\u05d3 \u05d4\u05d2\u05e9\u05ea \u05d4\u05ea\u05d1\u05d9\u05e2\u05d4 \u05e2\u05d3 \u05dc\u05e9\u05e0\u05d4 \u05de\u05de\u05d5\u05e2\u05d3 \u05d9\u05e6\u05d9\u05e8\u05ea \u05d4\u05e2\u05d9\u05dc\u05d4 \u05d5\u05de\u05e2\u05d1\u05e8 \u05dc\u05de\u05d5\u05e2\u05d3 \u05d6\u05d4 \u05ea\u05d7\u05d5\u05dc \u05d4\u05ea\u05d9\u05d9\u05e9\u05e0\u05d5\u05ea \u05e2\u05dc \u05d4\u05ea\u05d1\u05d9\u05e2\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.8.&nbsp; &nbsp; &nbsp; &nbsp; \u05d1\u05db\u05e4\u05d5\u05e3 \u05dc\u05db\u05dc \u05d3\u05d9\u05df, \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d1\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05dc\u05db\u05dc \u05e0\u05d6\u05e7 \u05de\u05db\u05dc \u05e1\u05d5\u05d2 \u05e9\u05d4\u05d5\u05d0, \u05e9\u05d9\u05d2\u05e8\u05dd \u05dc\u05dc\u05e7\u05d5\u05d7 \u05d0\u05d5 \u05dc\u05de\u05d9 \u05de\u05d8\u05e2\u05de\u05d5,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d0\u05dd \u05de\u05d9\u05d3\u05e2 \u05db\u05dc\u05e9\u05d4\u05d5 \u05e9\u05d4\u05d6\u05d9\u05df \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d1\u05de\u05d4\u05dc\u05da \u05e4\u05e2\u05d5\u05dc\u05ea \u05d1\u05d9\u05e6\u05d5\u05e2 \u05d4\u05d4\u05d6\u05de\u05e0\u05d4 \u05d9\u05d0\u05d1\u05d3 \u05d0\u05d5 \u05d9\u05d2\u05d9\u05e2 \u05dc\u05d2\u05d5\u05e8\u05dd \u05db\u05dc\u05e9\u05d4\u05d5 \u05e9\u05d0\u05d9\u05e0\u05d5 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d5\/\u05d0\u05d5 \u05d9\u05e2\u05e9\u05d4 \u05d1\u05d5 \u05e9\u05d9\u05de\u05d5\u05e9 \u05e9\u05dc\u05d0 \u05d1\u05d4\u05e8\u05e9\u05d0\u05d4.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.9.&nbsp; &nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05d0\u05d7\u05e8\u05d0\u05d9\u05ea \u05dc\u05db\u05dc \u05d0\u05d9\u05d7\u05d5\u05e8 \u05d0\u05d5 \u05e2\u05d9\u05db\u05d5\u05d1 \u05d1\u05d0\u05e1\u05e4\u05e7\u05d4 \u05d5\/\u05d0\u05d5 \u05dc\u05d0\u05d9-\u05d0\u05e1\u05e4\u05e7\u05d4 \u05e9\u05dc \u05d4\u05d6\u05de\u05e0\u05d4, \u05e9\u05e0\u05d2\u05e8\u05dd \u05db\u05ea\u05d5\u05e6\u05d0\u05d4 \u05de\"\u05db\u05d5\u05d7 \u05e2\u05dc\u05d9\u05d5\u05df\" \u05d5\/\u05d0\u05d5 \u05de\u05d0\u05d9\u05e8\u05d5\u05e2\u05d9\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05d1\u05e9\u05dc\u05d9\u05d8\u05ea\u05dd \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4, \u05dc\u05e8\u05d1\u05d5\u05ea \u05e9\u05d1\u05d9\u05ea\u05d5\u05ea, \u05d4\u05e9\u05d1\u05ea\u05d5\u05ea, \u05d0\u05e1\u05d5\u05e0\u05d5\u05ea \u05d8\u05d1\u05e2,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05de\u05d6\u05d2 \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d7\u05e8\u05d9\u05d2 \u05d5\u05db\u05d9\u05d5\u05e6\"\u05d1, \u05ea\u05e7\u05dc\u05d4 \u05d1\u05de\u05e2\u05e8\u05db\u05ea \u05d4\u05de\u05d7\u05e9\u05d5\u05d1 \u05d0\u05d5 \u05d1\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05d4\u05d8\u05dc\u05e4\u05d5\u05e0\u05d9\u05dd \u05e9\u05d9\u05e4\u05d2\u05e2\u05d5 \u05d1\u05d4\u05e9\u05dc\u05de\u05ea \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05db\u05d9\u05e9\u05d4 \u05d0\u05d5 \u05ea\u05e7\u05dc\u05d5\u05ea \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05d3\u05d5\u05d0\u05e8 \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.10.&nbsp; &nbsp; &nbsp; \u05e4\u05e8\u05d8\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df \u05d5\/\u05d0\u05d5 \u05d4\u05d9\u05d1\u05d5\u05d0\u05df \u05d5\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d1\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d9\u05d5\u05e4\u05d9\u05e2\u05d5 \u05e2\u05dc \u05d2\u05d1\u05d9 \u05d4\u05de\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d4\u05d6\u05de\u05e0\u05d4. \u05d4\u05d9\u05d4 \u05d5\u05d4\u05de\u05d9\u05d3\u05e2 \u05d0\u05d9\u05e0\u05d5 \u05d6\u05de\u05d9\u05df \u05e2\u05dc \u05d2\u05d1\u05d9 \u05d4\u05de\u05d5\u05e6\u05e8,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05e0\u05d9\u05ea\u05df \u05dc\u05e4\u05e0\u05d5\u05ea \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea \u05d4\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05d0\u05d5\u05e4\u05df \u05d4\u05d0\u05de\u05d5\u05e8 \u05d1\u05e1\u05e2\u05d9\u05e3 9 \u05dc\u05e2\u05d9\u05dc \u05dc\u05e7\u05d1\u05dc \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05e2 \u05d5\/\u05d0\u05d5 \u05de\u05d9\u05d3\u05e2 \u05e0\u05d5\u05e1\u05e3.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05d0\u05d7\u05e8\u05d0\u05d9\u05ea \u05dc\u05e9\u05d9\u05de\u05d5\u05e9 \u05e9\u05d9\u05e2\u05e9\u05d4 \u05d4\u05dc\u05e7\u05d5\u05d7 \u05e9\u05dc\u05d0 \u05d1\u05d4\u05ea\u05d0\u05dd \u05dc\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05d9\u05e6\u05e8\u05df.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.11.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05d0\u05d7\u05e8\u05d0\u05d9\u05ea, \u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05db\u05d0\u05dc\u05d4, \u05dc\u05ea\u05db\u05e0\u05d9\u05dd \u05d4\u05de\u05e4\u05d5\u05e8\u05e1\u05de\u05d9\u05dd \u05d1\u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05d4\u05e7\u05d9\u05d9\u05de\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05d5\u05d4\u05de\u05d5\u05d1\u05d9\u05dc\u05d9\u05dd \u05dc\u05d0\u05ea\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd \u05d0\u05dc\u05d9\u05d4\u05dd \u05e0\u05d9\u05ea\u05df \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d3\u05e8\u05da \u05d0\u05d5\u05ea\u05d4 \u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05ea (link).&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05de\u05ea\u05d7\u05d9\u05d9\u05d1\u05ea \u05db\u05d9 \u05d4\u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05ea \u05ea\u05d5\u05d1\u05d9\u05dc \u05d0\u05ea \u05d4\u05de\u05e9\u05ea\u05de\u05e9 \u05dc\u05d0\u05ea\u05e8 \u05e4\u05e2\u05d9\u05dc.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.12.&nbsp; &nbsp; &nbsp; \u05e0\u05d1\u05d4\u05d9\u05e8 \u05db\u05d9 \u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05d5\u05ea \u05d0\u05dc\u05d5 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05de\u05e4\u05e8\u05e1\u05de\u05ea \u05d0\u05d5\u05ea\u05dd \u05de\u05d8\u05e2\u05de\u05d4, \u05d0\u05d9\u05e0\u05d4 \u05de\u05e4\u05e7\u05d7\u05ea \u05e2\u05dc\u05d9\u05d4\u05dd \u05d0\u05d5 \u05d1\u05d5\u05d3\u05e7\u05ea \u05d0\u05d5\u05ea\u05dd, \u05d0\u05ea \u05de\u05d4\u05d9\u05de\u05e0\u05d5\u05ea\u05dd \u05d5\u05d0\u05ea \u05d7\u05d5\u05e7\u05d9\u05d5\u05ea\u05dd \u05d5\u05d0\u05ea \u05db\u05dc \u05d4\u05e7\u05e9\u05d5\u05e8 \u05dc\u05d0\u05d1\u05d8\u05d7\u05d4 \u05e9\u05dc\u05d4\u05dd \u05d5\u05dc\u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea \u05d4\u05d2\u05e0\u05ea \u05d4\u05e4\u05e8\u05d8\u05d9\u05d5\u05ea \u05e9\u05dc\u05d4\u05dd.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05e4\u05d9\u05db\u05da, \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d1\u05db\u05dc \u05d7\u05d1\u05d5\u05ea, \u05de\u05db\u05dc \u05e1\u05d5\u05d2 \u05e9\u05d4\u05d5\u05d0, \u05d1\u05db\u05dc \u05d4\u05e7\u05e9\u05d5\u05e8 \u05dc\u05d6\u05db\u05d5\u05d9\u05d5\u05ea \u05e2\u05dc \u05d4\u05e7\u05e0\u05d9\u05d9\u05df \u05d4\u05e8\u05d5\u05d7\u05e0\u05d9 \u05d0\u05d5 \u05db\u05dc \u05d6\u05db\u05d5\u05ea \u05d0\u05d7\u05e8\u05ea \u05e9\u05dc \u05e6\u05d3 \u05e9\u05dc\u05d9\u05e9\u05d9, \u05d1\u05d2\u05d9\u05df \u05d4\u05ea\u05d5\u05db\u05df \u05e9\u05d9\u05e4\u05d5\u05e8\u05e1\u05dd \u05d1\u05d3\u05e4\u05d9 \u05d4\u05d0\u05ea\u05e8 \u05d4\u05e9\u05d5\u05e0\u05d9\u05dd \u05d0\u05d5 \u05d1\u05db\u05dc \u05d0\u05ea\u05e8 \u05d0\u05d7\u05e8 \u05e9\u05de\u05e7\u05d5\u05e9\u05e8 \u05dc\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.13.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05d0\u05d7\u05e8\u05d0\u05d9\u05ea \u05dc\u05e9\u05d9\u05de\u05d5\u05e9 \u05e9\u05e2\u05d5\u05e9\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05dc\u05d0\u05ea\u05e8, \u05d1\u05d3\u05e4\u05d9\u05dd \u05e9\u05d0\u05d9\u05e0\u05dd \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8 \u05d0\u05d5 \u05d1\u05d0\u05ea\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05d4\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05de\u05ea\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05e6\u05d9\u05d9\u05ea \u05d5\u05dc\u05e7\u05d9\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d5\u05d4\u05ea\u05e0\u05d0\u05d9\u05dd \u05e9\u05dc \u05d0\u05d5\u05ea\u05dd \u05d0\u05ea\u05e8\u05d9\u05dd \u05d0\u05d5 \u05d3\u05e4\u05d9 \u05d0\u05d9\u05e0\u05d8\u05e8\u05e0\u05d8 \u05d5\u05dc\u05d4\u05ea\u05e7\u05e9\u05e8 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05dc\u05e1\u05e4\u05e7\u05d9\u05dd \u05e9\u05dc \u05d0\u05ea\u05e8\u05d9\u05dd \u05d0\u05dc\u05d4 \u05d0\u05d5 \u05d3\u05e4\u05d9\u05dd \u05d0\u05dc\u05d4 \u05d1\u05db\u05dc \u05d4\u05e7\u05e9\u05d5\u05e8 \u05dc\u05e0\u05d5\u05e9\u05d0\u05d9\u05dd \u05e9\u05d9\u05e2\u05dc\u05d5 \u05db\u05ea\u05d5\u05e6\u05d0\u05d4 \u05de\u05d4\u05db\u05e0\u05d9\u05e1\u05d4,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d3\u05e4\u05d3\u05d5\u05e3 \u05d0\u05d5 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d4\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.14.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05e1\u05dc\u05e7 \u05de\u05d4\u05d0\u05ea\u05e8 \u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05e9\u05e0\u05db\u05dc\u05dc\u05d5 \u05d1\u05d5 \u05d1\u05e2\u05d1\u05e8, \u05d0\u05d5 \u05dc\u05d4\u05d9\u05de\u05e0\u05e2 \u05de\u05d4\u05d5\u05e1\u05e4\u05ea \u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd- \u05d4\u05db\u05dc \u05dc\u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.15.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05de\u05ea\u05d7\u05d9\u05d9\u05d1\u05ea \u05e9\u05e9\u05d9\u05e8\u05d5\u05ea\u05d9 \u05d4\u05d0\u05ea\u05e8 \u05dc\u05d0 \u05d9\u05d5\u05e4\u05e8\u05e2\u05d5, \u05d9\u05d9\u05e0\u05ea\u05e0\u05d5 \u05db\u05e1\u05d3\u05e8\u05dd \u05d0\u05d5 \u05d1\u05dc\u05d0 \u05d4\u05e4\u05e1\u05e7\u05d5\u05ea, \u05d9\u05ea\u05e7\u05d9\u05d9\u05de\u05d5 \u05d5\u05dc\u05dc\u05d0 \u05d8\u05e2\u05d5\u05d9\u05d5\u05ea, \u05d5\u05d9\u05d4\u05d9\u05d5 \u05d7\u05e1\u05d9\u05e0\u05d9\u05dd \u05de\u05e4\u05e0\u05d9 \u05d2\u05d9\u05e9\u05d4 \u05d1\u05dc\u05ea\u05d9-\u05de\u05d5\u05e8\u05e9\u05d9\u05ea \u05dc\u05de\u05d7\u05e9\u05d1\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d5 \u05de\u05e4\u05e0\u05d9 \u05e0\u05d6\u05e7\u05d9\u05dd, \u05ea\u05e7\u05dc\u05d5\u05ea \u05d0\u05d5 \u05db\u05e9\u05dc\u05d9\u05dd &ndash;&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d5\u05d4\u05db\u05dc, \u05d1\u05d7\u05d5\u05de\u05e8\u05d4, \u05d1\u05ea\u05d5\u05db\u05e0\u05d4, \u05d1\u05e7\u05d5\u05d5\u05d9 \u05d5\u05d1\u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05d4\u05ea\u05e7\u05e9\u05d5\u05e8\u05ea, \u05d0\u05e6\u05dc \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d5 \u05d0\u05e6\u05dc \u05de\u05d9 \u05de\u05e1\u05e4\u05e7\u05d9\u05d4 \u05d5\u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d1\u05db\u05dc \u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05dc\u05e9\u05d9\u05d1\u05d5\u05e9 \u05d5\/\u05d0\u05d5 \u05dc\u05db\u05dc \u05ea\u05e7\u05dc\u05d4 \u05d8\u05db\u05e0\u05d9\u05ea \u05d4\u05e7\u05e9\u05d5\u05e8\u05d4 \u05d1\u05d4\u05e4\u05e2\u05dc\u05ea \u05d4\u05d0\u05ea\u05e8 \u05db\u05d0\u05de\u05d5\u05e8.&nbsp;&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05e0\u05da \u05de\u05e6\u05d4\u05d9\u05e8\u05d4 \u05db\u05d9 \u05d9\u05d3\u05d5\u05e2 \u05dc\u05da \u05e9\u05d4\u05d2\u05dc\u05d9\u05e9\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4, \u05d1\u05d9\u05df \u05d4\u05d9\u05ea\u05e8, \u05d1\u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc\u05d9\u05e9\u05d9\u05d9\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.16.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d4\u05d0 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05e9\u05e0\u05d5\u05ea \u05de\u05e2\u05ea \u05dc\u05e2\u05ea \u05d0\u05ea \u05de\u05d1\u05e0\u05d4 \u05d4\u05d0\u05ea\u05e8 \u05d4\u05db\u05d5\u05dc\u05dc \u05d1\u05d9\u05df \u05d4\u05d9\u05ea\u05e8, \u05d0\u05ea \u05de\u05e8\u05d0\u05d4\u05d5, \u05d4\u05d9\u05e7\u05e4\u05d5 \u05d5\u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea\u05d9\u05dd \u05d4\u05e0\u05d9\u05ea\u05e0\u05d9\u05dd \u05d1\u05d5 \u05d5\u05db\u05dc \u05d4\u05d9\u05d1\u05d8 \u05d0\u05d7\u05e8 \u05d4\u05db\u05e8\u05d5\u05da \u05d1\u05d4\u05dd. \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05de\u05e1\u05d5\u05d2 \u05d6\u05d4 \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05ea\u05e7\u05dc\u05d5\u05ea \u05d0\u05d5 \u05d0\u05d9-\u05e0\u05d5\u05d7\u05d5\u05ea \u05d5\u05db\u05d9\u05d5\"\u05d1.&nbsp; &nbsp; &nbsp;&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05de\u05d5\u05d1\u05d4\u05e8 \u05db\u05d9 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05dc\u05da \u05db\u05dc \u05d8\u05e2\u05e0\u05d4, \u05d5\/\u05d0\u05d5 \u05ea\u05d1\u05d9\u05e2\u05d4, \u05d5\/\u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05db\u05dc\u05e4\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d1\u05e9\u05dc \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd \u05db\u05d0\u05de\u05d5\u05e8 \u05d0\u05d5 \u05d4\u05ea\u05e7\u05dc\u05d5\u05ea \u05e9\u05d9\u05ea\u05e8\u05d7\u05e9\u05d5 \u05ea\u05d5\u05da \u05d1\u05d9\u05e6\u05d5\u05e2\u05dd.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05d4\u05e4\u05e1\u05d9\u05e7 \u05d1\u05db\u05dc \u05e2\u05ea \u05d0\u05ea \u05de\u05ea\u05df \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea\u05d9\u05dd \u05d1\u05d0\u05ea\u05e8, \u05db\u05d5\u05dc\u05dd \u05d0\u05d5 \u05d7\u05dc\u05e7\u05dd \u05d5\u05ea\u05e9\u05ea\u05d3\u05dc \u05dc\u05e4\u05e8\u05e1\u05dd \u05d1\u05d0\u05ea\u05e8 \u05d4\u05d5\u05d3\u05e2\u05d4 \u05e2\u05dc \u05d4\u05e4\u05e1\u05e7\u05ea \u05e9\u05d9\u05e8\u05d5\u05ea\u05d9\u05dd \u05d0\u05dc\u05d4 \u05dc\u05e4\u05d7\u05d5\u05ea 7 \u05d9\u05de\u05d9\u05dd \u05de\u05e8\u05d0\u05e9.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.17.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05d1\u05d8\u05dc \u05e8\u05d9\u05e9\u05d5\u05dd \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d0\u05d5 \u05dc\u05d7\u05e1\u05d5\u05dd \u05d0\u05ea \u05d4\u05d2\u05d9\u05e9\u05d4 \u05d0\u05dc\u05d9\u05d5 \u05d1\u05db\u05dc \u05e2\u05ea \u05d5\u05d1\u05e4\u05e8\u05d8 \u05d0\u05dd \u05d4\u05e1\u05d9\u05d1\u05d5\u05ea \u05d4\u05df:\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.17.1.&nbsp; &nbsp;\u05de\u05e1\u05d9\u05e8\u05ea \u05e4\u05e8\u05d8\u05d9\u05dd \u05e9\u05d2\u05d5\u05d9\u05d9\u05dd \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d9\u05d9\u05dd \u05d1\u05e2\u05ea \u05d4\u05d4\u05e8\u05e9\u05de\u05d4 \u05dc\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.17.2.&nbsp; &nbsp;\u05d1\u05d9\u05e6\u05d5\u05e2 \u05de\u05e2\u05e9\u05d4 \u05d0\u05d5 \u05de\u05d7\u05d3\u05dc \u05d4\u05e4\u05d5\u05d2\u05e2\u05d9\u05dd \u05d0\u05d5 \u05d4\u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d5 \u05d1\u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc\u05d9\u05e9\u05d9\u05d9\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.17.3.&nbsp; &nbsp;\u05d1\u05e2\u05ea \u05d4\u05e4\u05e8\u05ea \u05ea\u05e0\u05d0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8, \u05d5\/\u05d0\u05d5 \u05d1\u05e2\u05ea \u05d4\u05e4\u05e8\u05ea \u05d4\u05e1\u05db\u05dd \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d5\/\u05d0\u05d5 \u05d1\u05e2\u05ea \u05d4\u05e4\u05e8\u05ea \u05db\u05dc \u05d3\u05d9\u05df.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.17.4.&nbsp; &nbsp;\u05d1\u05d9\u05e6\u05d5\u05e2 \u05e4\u05e2\u05d5\u05dc\u05ea \u05de\u05e0\u05d9\u05e2\u05d4 \u05d5\u05d4\u05e1\u05ea\u05d4 \u05de\u05e8\u05d9\u05e9\u05d5\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd \u05dc\u05d0\u05ea\u05e8.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.18.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d0 \u05d1\u05db\u05dc \u05d0\u05d7\u05e8\u05d9\u05d5\u05ea, \u05d1\u05d9\u05df \u05d0\u05dd \u05d1\u05de\u05d9\u05e9\u05e8\u05d9\u05df \u05d5\u05d1\u05d9\u05df \u05d0\u05dd \u05d1\u05e2\u05e7\u05d9\u05e4\u05d9\u05df, \u05de\u05db\u05dc \u05e1\u05d9\u05d1\u05d4 \u05e9\u05d4\u05d9\u05d0, \u05d1\u05de\u05e7\u05e8\u05d4 \u05d5\u05d1\u05d5 \u05dc\u05d0 \u05ea\u05d4\u05d0 \u05d1\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea\u05da \u05dc\u05e2\u05e9\u05d5\u05ea \u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8, \u05d1\u05d9\u05df \u05d0\u05dd \u05d1\u05d0\u05d5\u05e4\u05df \u05d7\u05dc\u05e7\u05d9 \u05d5\u05d1\u05d9\u05df \u05d0\u05dd \u05d1\u05d0\u05d5\u05e4\u05df \u05de\u05dc\u05d0, \u05d5\u05dc\u05d1\u05e6\u05e2 \u05e2\u05e1\u05e7\u05d0\u05d5\u05ea \u05d1\u05d0\u05de\u05e6\u05e2\u05d5\u05ea\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.19.&nbsp; &nbsp; &nbsp; \u05d1\u05de\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d8\u05e2\u05d5\u05ea \u05e1\u05d5\u05e4\u05e8, \u05d8\u05e2\u05d5\u05ea \u05d1\u05ea\u05d9\u05d0\u05d5\u05e8 \u05d4\u05de\u05d5\u05e6\u05e8 \u05d5\/\u05d0\u05d5 \u05d1\u05de\u05d7\u05d9\u05e8\u05d5, \u05d1\u05ea\u05e0\u05d0\u05d9 \u05d4\u05ea\u05e9\u05dc\u05d5\u05dd, \u05d5\/\u05d0\u05d5 \u05d1\u05db\u05dc \u05de\u05d9\u05d3\u05e2 \u05d0\u05d7\u05e8 \u05d4\u05de\u05e4\u05d5\u05e8\u05d8 \u05d1\u05d0\u05ea\u05e8, \u05d8\u05e2\u05d5\u05ea \u05d1\u05e4\u05e8\u05d8\u05d9\u05d9\u05da \u05db\u05e4\u05d9 \u05e9\u05d9\u05d5\u05e4\u05d9\u05e2\u05d5 \u05d1\u05de\u05d0\u05d2\u05e8\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4, \u05ea\u05d4\u05d0 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05e8\u05e9\u05d0\u05d9\u05ea, \u05d0\u05da \u05dc\u05d0 \u05d7\u05d9\u05d9\u05d1\u05ea,&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05dc\u05d1\u05d8\u05dc \u05d0\u05ea \u05d4\u05e2\u05e1\u05e7\u05d4 \u05d1\u05de\u05dc\u05d5\u05d0\u05d4 \u05d0\u05d5 \u05d1\u05d7\u05dc\u05e7\u05d4 \u05d5\u05dc\u05d4\u05d7\u05d6\u05d9\u05e8 \u05dc\u05da \u05db\u05dc \u05ea\u05e9\u05dc\u05d5\u05dd \u05e9\u05e0\u05e9\u05d0\u05ea \u05d1\u05d5.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.20.&nbsp; &nbsp; &nbsp; \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05ea\u05e8 \u05d5\u05d1\u05ea\u05db\u05e0\u05d9\u05dd \u05e0\u05d9\u05ea\u05df \u05dc\u05e9\u05d9\u05de\u05d5\u05e9 \u05db\u05de\u05d5 \u05e9\u05d4\u05d5\u05d0 (\u003Cb\u003EAS IS\u003C\/b\u003E). \u05d4\u05d7\u05d1\u05e8\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05ea\u05d0\u05d9\u05de\u05dd \u05dc\u05e6\u05e8\u05db\u05d9\u05da \u05d4\u05d0\u05d9\u05e9\u05d9\u05d9\u05dd. \u05dc\u05d0 \u05ea\u05d4\u05d0 \u05dc\u05dc\u05e7\u05d5\u05d7 \u05db\u05dc \u05d8\u05e2\u05e0\u05d4, \u05ea\u05d1\u05d9\u05e2\u05d4 \u05d0\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05d2\u05d9\u05df \u05d3\u05d9\u05d5\u05e7\u05dd \u05d0\u05d5 \u05d4\u05ea\u05d0\u05de\u05ea\u05dd \u05dc\u05e6\u05e8\u05db\u05d9\u05da.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea\u05d9\u05dd \u05d5\u05d4\u05d5\u05e8\u05d3\u05ea \u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05de\u05d4\u05d0\u05ea\u05e8 \u05d9\u05e2\u05e9\u05d5, \u05d0\u05e4\u05d5\u05d0, \u05e2\u05dc \u05d0\u05d7\u05e8\u05d9\u05d5\u05ea\u05da \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9\u05ea \u05d5\u05d4\u05de\u05dc\u05d0\u05d4.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05d7\u05d1\u05e8\u05d4 \u05d5\/\u05d0\u05d5 \u05de\u05d9 \u05de\u05d8\u05e2\u05de\u05d4 \u05dc\u05d0 \u05d9\u05d9\u05e9\u05d0\u05d5 \u05d1\u05d0\u05d7\u05e8\u05d9\u05d5\u05ea \u05dc\u05db\u05dc \u05e0\u05d6\u05e7 \u05d9\u05e9\u05d9\u05e8 \u05d0\u05d5 \u05e2\u05e7\u05d9\u05e3, \u05db\u05e1\u05e4\u05d9 \u05d0\u05d5 \u05d0\u05d7\u05e8, \u05e9\u05d9\u05d9\u05d2\u05e8\u05dd \u05dc\u05dc\u05e7\u05d5\u05d7 \u05db\u05ea\u05d5\u05e6\u05d0\u05d4 \u05de\u05e9\u05d9\u05de\u05d5\u05e9 \u05d0\u05d5 \u05d4\u05e1\u05ea\u05de\u05db\u05d5\u05ea \u05e2\u05dc \u05d4\u05de\u05d9\u05d3\u05e2 \u05d4\u05de\u05ea\u05e4\u05e8\u05e1\u05dd.\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp;13.21.&nbsp; &nbsp; &nbsp; \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d4\u05d0 \u05e8\u05e9\u05d0\u05d9\u05ea, \u05e2\u05dc \u05e4\u05d9 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d3\u05e2\u05ea\u05d4 \u05d4\u05d1\u05dc\u05e2\u05d3\u05d9, \u05dc\u05d4\u05e2\u05d1\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d1\u05e2\u05dc\u05d5\u05ea \u05d1\u05d0\u05ea\u05e8 \u05d6\u05d4 \u05dc\u05e6\u05d3 \u05e9\u05dc\u05d9\u05e9\u05d9, \u05d6\u05d0\u05ea \u05d1\u05ea\u05e0\u05d0\u05d9 \u05db\u05d9 \u05d6\u05db\u05d5\u05d9\u05d5\u05ea\u05d9\u05d9\u05da \u05e2\u05dc \u05e4\u05d9 \u05ea\u05e7\u05e0\u05d5\u05df \u05d6\u05d4 \u05d9\u05de\u05e9\u05d9\u05db\u05d5 \u05dc\u05d7\u05d5\u05dc.&nbsp;\u003Cbr \/\u003E&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05dc\u05e7\u05d5\u05d7 \u05de\u05e1\u05db\u05d9\u05dd \u05db\u05d9 \u05d4\u05d7\u05d1\u05e8\u05d4 \u05ea\u05d4\u05d0 \u05e8\u05e9\u05d0\u05d9\u05ea \u05dc\u05d4\u05e2\u05d1\u05d9\u05e8 \u05d0\u05ea \u05e4\u05e8\u05d8\u05d9\u05d5, \u05d4\u05de\u05e6\u05d5\u05d9\u05d9\u05dd \u05d1\u05d9\u05d3\u05d9\u05d4, \u05dc\u05d9\u05d3\u05d9 \u05e6\u05d3 \u05e9\u05dc\u05d9\u05e9\u05d9 \u05d1\u05de\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d4\u05e2\u05d1\u05e8\u05ea \u05d4\u05d1\u05e2\u05dc\u05d5\u05ea \u05db\u05d0\u05de\u05d5\u05e8.\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;\u003Cstrong\u003E14.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003C\/strong\u003E\u003Cb\u003E\u003Cspan\u003E\u003Cstrong\u003E\u05d3\u05d9\u05df \u05d5\u003C\/strong\u003E\u05de\u05e7\u05d5\u05dd \u05e9\u05d9\u05e4\u05d5\u05d8\u003C\/span\u003E\u003C\/b\u003E\u003C\/p\u003E\r\n\u003Cp dir=\"RTL\"\u003E&nbsp; &nbsp; &nbsp;14.1.&nbsp; &nbsp; &nbsp; &nbsp;\u05d4\u05ea\u05e0\u05d0\u05d9\u05dd \u05d5\u05d4\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05de\u05e4\u05d5\u05e8\u05d8\u05d9\u05dd \u05d1\u05ea\u05e0\