    ], function($,idus){
        var form = $(".ajaxnewsletter-post");
        var submit = $('.ajaxnewsletter-subscribe',form);
        var news = $('.ajaxnewsletter');
        var input = $('input[name=email]',form);
        var dataForm = form.mage('validation');
        dataForm.on('submit',function(e){
            e.stopPropagation();
            e.stopImmediatePropagation();
            e.preventDefault();
            if ($(this).valid()) {
                var url = "https://www.opticana.co.il/ajaxnewsletter/subscriber/new/";
                $('.ajaxnewsletter-response',news).text('');
                // if(input.val() == '')return;
                // if($('div.mage-error:visible',form).length) return;
                form.css('opacity','0.5');
                $(submit,input).attr('disabled','disabled');
                $.ajax({
                   type: 'POST',
                   dataType: 'json',
                   url: url,
                   data: form.serialize(),
                   success: function(data){
                        var response = $('.ajaxnewsletter-response',news).text(data.msg);
                        if(data.action == 'Success'){
                            news.addClass('success').removeClass('error');
                            $('.ajaxnewsletter-response').attr('id','ajaxnewsletter-response-success');
                            $('input',form).val('');

                            //push data Layer footer Newsletter
                            idus.getDataLayer().dataLayerNewsletter('footer','add');
                        }else{
                            news.addClass('error').removeClass('success');
                        }
                        form.css('opacity','1');
                        $(submit,input).removeAttr('disabled');
                   }
                });
            }
        });

    });



